/*
  Cardio Part 1 Diseases tool: Hypertension (Parts I–III) entries.

  lecture -> disease -> sections (reference) + questions (practice bank).
  Sources: source-material/cardio-part-1/text/hypertension-part-1/2/3.md and the
  "Hypertension, Parts I, II and III" objective block. The Hypertension Crisis
  block is not covered here beyond the urgency/emergency cutoffs the decks give.
  Antihypertensive classes appear in the treatment sections of the disease
  path they are taught for (first-line, compelling indications, resistant HTN,
  special populations).

  Question ids are "<disease id>|<index>" and progress is saved against them:
  only APPEND questions to a disease; never insert, delete, or reorder.
  `correct` is zero-based; the engine shuffles answer order every time.
*/
(function () {
  "use strict";

  var H = window.DiseaseContent;
  var Tbl = H.Tbl, HY = H.HY, Mn = H.Mn, S = H.S, Q = H.Q, D = H.D, L = H.L;

  function C(text) { return "<p><em>Clarification (standard reference):</em> " + text + "</p>"; }

  // ---------------------------------------------------------------------
  // Shared reference blocks
  // ---------------------------------------------------------------------
  var stageTable = Tbl(["Classification (AHA/ACC)", "Systolic", "", "Diastolic"], [
    ["Normal", "&lt;120", "and", "&lt;80"],
    ["Elevated BP", "120–129", "and", "&lt;80"],
    ["<strong>Stage 1 HTN</strong>", "130–139", "<strong>or</strong>", "80–89"],
    ["<strong>Stage 2 HTN</strong>", "≥140", "<strong>or</strong>", "≥90"],
    ["Isolated systolic HTN", "≥130", "and", "&lt;80"],
    ["Isolated diastolic HTN", "&lt;130", "and", "≥80"],
    ["Hypertensive urgency", "&gt;180", "or", "&gt;120"],
    ["Hypertensive emergency (end-organ damage)", "&gt;180", "or", "&gt;120"]
  ]);

  var secondaryCluesTable = Tbl(["Cause", "Clue in the history / exam / labs", "Test taught"], [
    ["<strong>Renal artery stenosis</strong>", "AKI after starting ACEI/ARB, refractory HTN with vascular risk factors, recurrent flash pulmonary edema, <strong>abdominal bruit</strong>; young woman (FMD)", "Duplex Doppler US → CTA/MRA → <strong>angiogram (gold standard)</strong>"],
    ["<strong>Coarctation of the aorta</strong>", "Arm BP/pulses &gt; leg; <strong>radial–femoral delay</strong>; chest bruit; <strong>rib notching</strong>", "Echo (children), CTA (adults)"],
    ["<strong>Pheochromocytoma</strong>", "Episodic HTN with <strong>sweating, headache, palpitations</strong>, pallor", "<strong>24-h urine metanephrines + catecholamines</strong> → adrenal CT/MRI"],
    ["<strong>Primary hyperaldosteronism</strong>", "Generalized <strong>weakness + persistent hypokalemia</strong>, metabolic alkalosis", "Not specified on the slides"],
    ["<strong>Cushing’s syndrome</strong>", "Glucocorticoid excess (pituitary ACTH adenoma, adrenal adenoma, ectopic ACTH/SCLC)", "Not specified on the slides"],
    ["<strong>Thyroid disease</strong>", "Heat/cold intolerance, sweating, low energy, brady- or tachycardia", "<strong>TSH</strong>"],
    ["<strong>Polycystic kidney disease</strong>", "Flank pain, hematuria, UTI, stones, enlarged kidneys; family history (AD)", "—"],
    ["<strong>OSA</strong>", "Resistant HTN, heavy snoring, obesity, daytime sleepiness", "—"],
    ["<strong>Medications / substances</strong>", "OTC meds, OCPs, alcohol, cocaine, meth, licorice, St. John’s wort", "History"]
  ]);

  var drugOverviewTable = Tbl(["Class", "Role in HTN", "Signature adverse effects", "Avoid / caution"], [
    ["<strong>Thiazide</strong> (chlorthalidone, indapamide, HCTZ)", "<strong>First line</strong>; best in Black patients", "↓K, ↓Na, ↓Mg, <strong>↑Ca</strong>, ↑uric acid (gout), ↑glucose", "Gout, incontinence, SSRI use, hyponatremia, balance issues"],
    ["<strong>ACE inhibitor</strong> (-pril)", "<strong>First line</strong>; DM, CKD/proteinuria, HFrEF, post-MI", "<strong>Dry cough</strong>, ↑K, ↑creatinine, <strong>angioedema</strong>", "<strong>Pregnancy (renal agenesis)</strong>; never with an ARB"],
    ["<strong>ARB</strong> (-sartan)", "<strong>First line</strong>; same indications as ACEI", "↑K, ↑creatinine; less cough/angioedema", "Pregnancy; never with an ACEI"],
    ["<strong>DHP CCB</strong> (-dipine)", "<strong>First line</strong>; best in Black patients", "Peripheral edema, flushing, HA, reflex tachycardia (short-acting)", "Short-acting forms"],
    ["<strong>Non-DHP CCB</strong> (verapamil, diltiazem)", "Rate control (AF)", "Bradycardia, AV block, constipation (verapamil)", "Decompensated HFrEF, SSS, 2nd/3rd AVB; caution with BB"],
    ["<strong>Beta-blocker</strong> (-olol)", "Later line; compelling cardiac indications", "Bradycardia/heart block, fatigue, impotence, masks hypoglycemia", "Abrupt stop; asthma/COPD; DM or age &gt;60 without indication"],
    ["<strong>Aldosterone antagonist</strong>", "HFrEF; 4th drug in resistant HTN", "<strong>Hyperkalemia</strong>; gynecomastia (spironolactone)", "With ACEI/ARB/K supplements, GFR &lt;50"],
    ["<strong>α1-blocker</strong> (-zosin)", "HTN + BPH (not monotherapy)", "Orthostasis, <strong>first-dose syncope</strong>", "Older adults with falls"],
    ["<strong>Central α2-agonist</strong>", "Methyldopa (pregnancy), clonidine (ESRD)", "<strong>Rebound HTN</strong>, sedation, dry mouth", "Poor adherence (clonidine)"],
    ["<strong>Direct vasodilator</strong> (hydralazine, minoxidil)", "CKD/ESRD; hydralazine in HF combos", "Edema, reflex tachycardia, angina; <strong>drug-induced lupus</strong> (hydralazine), <strong>hair growth</strong> (minoxidil)", "CAD (vascular steal)"]
  ]);

  var compellingTable = Tbl(["Compelling indication", "Preferred regimen (lecture)"], [
    ["<strong>HFrEF</strong> (systolic dysfunction)", "ACEI or ARB + <strong>beta-blocker</strong> + <strong>aldosterone antagonist</strong> + diuretic — get at least the first 2–3 on board; <strong>avoid non-DHP CCB</strong>"],
    ["<strong>Post-MI</strong>", "<strong>Beta-blocker + ACEI or ARB</strong> — get both on board"],
    ["<strong>CAD</strong>", "Beta-blocker, ACEI or ARB, then a DHP-CCB or thiazide"],
    ["<strong>Atrial fibrillation</strong>", "<strong>Beta-blocker or non-DHP CCB</strong>, ACEI or ARB, then thiazide"],
    ["<strong>Diabetes</strong>", "ACEI or ARB, then DHP-CCB or thiazide"],
    ["<strong>CKD / proteinuria</strong>", "ACEI or ARB, then DHP-CCB or thiazide"],
    ["<strong>Recurrent stroke prevention</strong>", "ACEI or ARB, then thiazide or DHP-CCB"]
  ]);

  window.CARDIO_DISEASES_HYPERTENSION = L("hypertension", "Hypertension", [

    // ------------------------------------------------------------------
    D("htn-primary", "Primary (Essential) Hypertension", "Sustained BP ≥130/80 with no single identifiable cause — 90–95% of all hypertension. Usually silent and found on screening; the diagnosis needs repeated, properly measured readings, and treatment pairs lifestyle change with first-line drugs (thiazide, ACEI/ARB, or CCB).", [
      S("epidemiology", "Epidemiology, Burden, and Social Determinants", Tbl(["", "Global", "United States"], [
        ["Scale", "&gt;1 billion people; leading cause of CVD and premature death; &gt;9.4 million deaths/yr", "<strong>~119 million (~48% of adults)</strong> with BP ≥130/80; most common CV disease; &gt;685K deaths"],
        ["Distribution", "Highest prevalence <strong>Africa (27%)</strong>, lowest <strong>Americas (18%)</strong>", "Men (50%) &gt; women (44%); <strong>Blacks (56%)</strong> &gt; Whites (48%) &gt; Asians (46%) &gt; Hispanics (39%); <strong>70% of adults &gt;65</strong>"],
        ["Awareness / control", "46% unaware; &lt;50% treated; <strong>1 in 5 controlled</strong>", "<strong>~1 in 4 controlled</strong> (Whites 32% best, Asians 19% worst); 1 in 5 unaware"]
      ]) + "<p>HTN is the most common reason non-pregnant adults visit a PCP and the most common indication for a prescription drug in the US (~$131 billion/yr). It raises the relative risk of <strong>CAD, HF, stroke, AF, CKD, PAD, and dementia 2–4 fold</strong>; the lowest CV and renal risk is at about <strong>115/75 or less</strong>, and CVD risk <strong>doubles for every 20/10 mmHg</strong> above 115/75.</p>" + Tbl(["Controlling BP to goal reduces", "By"], [
        ["Heart failure", "<strong>~50%</strong>"],
        ["Stroke", "30–40%"],
        ["MI", "20–25%"],
        ["Overall mortality", "11%"]
      ]) + "<p><strong>Social determinants of health</strong> (CDC’s 5 areas): healthcare access and quality, education access and quality, social and community context, economic stability, neighborhood and work environment. Economically disadvantaged patients have <strong>higher rates of HTN and are less likely to be controlled</strong>. Assess health literacy, tailor counseling to it, and ask about barriers to treatment.</p>" + HY("Biggest payoff of BP control: ~50% fewer heart-failure events. Lowest risk is at ≤115/75; risk doubles with each 20/10 above it.")),
      S("physiology", "BP Regulation Review", "<p><strong>MAP = CO × TPR</strong> (CO = SV × HR). A MAP of <strong>70–100 mmHg</strong> keeps tissues perfused. <strong>MAP = [(2 × DBP) + SBP] / 3</strong> (e.g., 130/80 → 97).</p>" + Tbl(["Control system", "Speed", "How it works"], [
        ["<strong>Baroreceptor reflex</strong> (carotid sinus, aortic arch)", "Short term (minutes–hours), <strong>neural</strong>", "↑ stretch → ↑ firing to the medullary CV center → <strong>sympathetic inhibited, parasympathetic activated</strong>; ↓ stretch does the opposite"],
        ["<strong>RAAS</strong>", "Long term, <strong>humoral</strong>", "Renin released by (1) renal sympathetic NE on <strong>β1 receptors</strong> of JG cells, (2) JG-cell baroreceptors sensing low afferent arteriole pressure, (3) <strong>macula densa</strong> sensing low NaCl"],
        ["Chemoreceptors", "—", "Peripheral (carotid/aortic): ↓PO2 → vasoconstriction; central (medulla): ↑PCO2 / ↓CSF pH → sympathetic outflow"],
        ["Volume receptors (venous side)", "—", "↑ stretch → ↓ADH, <strong>↑ANP</strong> (vasodilation), ↓RAAS"]
      ]) + "<p><strong>Angiotensin II</strong>: vasoconstriction, aldosterone release, proximal tubule Na and bicarbonate reabsorption, thirst, and ADH (vasopressin) release. <strong>Tubuloglomerular feedback</strong>: high NaCl at the macula densa → ATP → afferent vasoconstriction (↓GFR); low NaCl → prostaglandins → vasodilation (↑GFR).</p>" + HY("Low pressure OR low sodium at the kidney → renin → angiotensin II → vasoconstriction + aldosterone → BP rises.")),
      S("pathophysiology", "Pathophysiology and Risk Factors", "<p>No single known mechanism — HTN results from <strong>increased cardiac output and/or peripheral resistance</strong> driven by several contributors:</p><ul><li><strong>Sympathetic overactivity</strong> → ↑ vascular tone</li><li><strong>Genetics</strong> — twice as common with 1–2 hypertensive parents</li><li><strong>Reduced adult nephron mass</strong> (genetic, fetal, lifetime events)</li><li><strong>Disordered sodium handling</strong> — natriuresis after salt intake is impaired</li><li><strong>Immunologic</strong> — renal immune-cell infiltration; immunosuppression lowers BP</li><li><strong>Developmental</strong> — abnormal aortic elasticity or reduced capillary network (prematurity)</li></ul>" + Tbl(["Non-modifiable", "Modifiable"], [
        ["Family history (2× risk)", "<strong>Obesity</strong> (↑ volume, CO, sympathetic outflow, RAAS)"],
        ["<strong>African American race</strong> — onset ~10 years earlier, more severe, more complications", "Diabetes and dyslipidemia"],
        ["Male sex", "CKD / reduced nephron mass"],
        ["Advancing age (especially systolic HTN)", "<strong>Alcohol &gt;2 drinks/day</strong> (↑ catecholamines); binges"],
        ["Psychosocial stress (hostility, impatience, depression)", "<strong>High-sodium, low-potassium diet</strong>"],
        ["Low socioeconomic status", "Sedentary lifestyle; <strong>smoking</strong> (↑ norepinephrine); <strong>sleep &lt;7 h</strong>"]
      ]) + "<p>Other contributors: <strong>polycythemia</strong> (↑ viscosity) and <strong>NSAIDs</strong> (raise BP ~5 mmHg on average).</p>" + HY("Counseling message: many factors cause primary HTN — only some can be changed. Start lifestyle change (motivational interviewing) and often a drug while it takes effect.")),
      S("diagnosis", "Screening, Staging, and Making the Diagnosis", "<p><strong>Screening:</strong> every <strong>3–5 years</strong> at age 18–39 with normal BP and no risk factors; <strong>annually</strong> at age ≥40 or with risk factors (prior BP &gt;130/80, African American, overweight/obese, dyslipidemia, DM, smoking, high-salt diet).</p>" + stageTable + "<ul><li>If systolic and diastolic fall in different categories, the <strong>higher category</strong> sets the stage.</li><li>Definitions apply to adults on no antihypertensives who are not acutely ill; once on medication, a patient is <strong>always called hypertensive</strong> unless lifestyle change gets them off drugs with normal BP.</li></ul><p><strong>Diagnostic criteria:</strong> the <strong>average of ≥2 seated readings</strong> 1–2 min apart on <strong>≥2 separate visits</strong>. <strong>Out-of-office monitoring (ABPM preferred, or HBPM)</strong> confirms the diagnosis; if unavailable, repeat office readings within 1–2 weeks.</p>" + Tbl(["Single-visit diagnosis is allowed only when", ""], [
        ["BP <strong>≥180/≥120</strong>", "Hypertensive urgency or emergency"],
        ["BP <strong>≥160/≥100</strong> with known target-organ damage", "CAD, HF, LVH, stroke, hypertensive retinopathy, CKD"]
      ]) + "<p><strong>White coat hypertension:</strong> office ≥130/80 but daytime ABPM or HBPM &lt;130/80 → not HTN; reassess periodically.</p>" + HY("One reading almost never diagnoses HTN — except ≥180/120, or ≥160/100 with known end-organ damage.")),
      S("measurement", "Measuring BP: Office, Home, and Ambulatory", "<p><strong>Office technique:</strong> no exercise, caffeine, or smoking for 30 min; empty bladder; seated with back supported and feet flat for <strong>5 min</strong>; cuff on a bare arm; arm supported at <strong>heart level</strong> (otherwise BP reads 10–12 mmHg high); <strong>no talking</strong>; ideally an automated oscillometric device with no staff in the room. Measure <strong>both arms</strong> at the first visit and use the higher arm thereafter. Check orthostatics (supine 5 min, then 1–3 min standing): drop ≥20 systolic and/or ≥10 diastolic.</p>" + Tbl(["Arm circumference", "Cuff"], [
        ["22–26 cm", "Small adult"], ["27–34 cm", "Adult"], ["35–44 cm", "Large adult"], ["45–52 cm", "Adult thigh"]
      ]) + C("the cuff bladder should encircle about 80% of the arm circumference (the slide says “arm length”).") + Tbl(["Error", "BP falsely raised by"], [
        ["Talking during the reading", "<strong>17/13</strong> (largest)"],
        ["Cuff too small", "6–18 / 4–13"],
        ["No 5-minute rest", "12/6"],
        ["Back not supported", "6/8"]
      ]) + Tbl(["Method", "Utility"], [
        ["<strong>ABPM</strong> (every 15–20 min by day, 30–60 min at night, 24 h)", "<strong>Preferred for diagnosing HTN and white coat HTN</strong>; best predictor of target-organ damage and CV events; <strong>only method that reliably captures nocturnal BP</strong> (non-dippers); often hard to get covered by insurance"],
        ["<strong>HBPM</strong>", "Verify the device in clinic; seated, rested ≥5 min; 2 readings 1 min apart each morning (before meds) and evening (before dinner) for <strong>2 weeks after a medication change or 1 week before a visit</strong>; tracks response, improves adherence, helps detect white coat HTN"],
        ["<strong>Office</strong>", "≥2 readings 1–2 min apart; confirm in the contralateral arm"]
      ]) + Tbl(["Stage", "Clinic", "HBPM / daytime ABPM", "Nighttime ABPM", "24-h ABPM"], [
        ["Stage 1", "130–139/80–89", "130/80", "110/65", "125/75"],
        ["Stage 2", "140/90", "135/85", "120/70", "130/80"]
      ]) + "<p><strong>Non-dippers:</strong> BP normally falls ~10–20% during sleep (the deck cites ~15%); failure to dip adds CV risk and is detectable only on ABPM.</p>" + HY("Talking raises BP more than any other technique error (17/13). ABPM is the preferred diagnostic method and the only reliable nocturnal one.")),
      S("evaluation", "History, Exam, and Initial Work-up", "<p>At diagnosis, look for <strong>target-organ damage</strong>, <strong>CV risk factors</strong>, and <strong>secondary causes</strong>.</p>" + Tbl(["Area", "What to look for"], [
        ["History", "Prior HF, OSA, CKD, stroke/TIA, DM, PAD; chest pain, dyspnea, edema, headaches, claudication; OTC meds, OCPs, alcohol, illicit drugs"],
        ["Vitals", "BP (both arms), height, weight, <strong>waist circumference</strong>"],
        ["Eyes", "Cotton wool spots, <strong>AV nicking</strong>, arteriolar narrowing, hemorrhages, exudates, papilledema"],
        ["Vessels", "<strong>Radial–femoral delay</strong> (coarctation), weak pedal pulses (PAD), carotid/abdominal/femoral <strong>bruits</strong>"],
        ["Heart / lungs", "Heave, <strong>displaced apical impulse</strong>, <strong>S4</strong>; rales"],
        ["Neuro", "Neurologic exam"]
      ]) + "<p><strong>CV risk assessment:</strong> tobacco, high LDL / low HDL, DM, obesity (BMI ≥30), inactivity, age (men &gt;55, women &gt;65), eGFR &lt;60, microalbuminuria, family history of premature CAD (male relative &lt;55, female &lt;65). Estimate 10-year risk with the <strong>PREVENT</strong> (or ASCVD) calculator.</p>" + Tbl(["Initial labs for new HTN", "Looking for"], [
        ["Urinalysis", "Protein"],
        ["Fasting glucose and A1c", "Diabetes"],
        ["CBC", "Hematocrit (polycythemia, anemia of CKD)"],
        ["Electrolytes: Na, K, creatinine/eGFR, calcium", "CKD, hypokalemia (aldosteronism), baseline before drugs"],
        ["TSH", "Thyroid disease"],
        ["Fasting lipid panel (12-h fast)", "Dyslipidemia"],
        ["<strong>Baseline ECG</strong>", "<strong>LVH</strong> — echo if abnormal"]
      ]) + Mn("New-HTN labs: “U-GLEE-TL”", "UA, Glucose/A1c, Lytes (Na, K, Cr, Ca), EKG, ...hEmatocrit (CBC), TSH, Lipids.")),
      S("treatment-approach", "Treatment: Goals, When to Start Drugs, and Lifestyle", "<p><strong>Goal: &lt;130/80</strong> for treated patients (ACC/AHA). Lifestyle change is part of every plan and is discussed at <strong>every visit</strong> using <strong>motivational interviewing</strong>.</p>" + Tbl(["Category", "Initial plan (2025 AHA/ACC)"], [
        ["Normal &lt;120/&lt;80", "Promote healthy lifestyle; reassess yearly"],
        ["Elevated 120–129/&lt;80", "Lifestyle; reassess in 3–6 months"],
        ["Stage 1 + CVD, DM, CKD, or 10-yr risk <strong>≥7.5%</strong>", "<strong>Lifestyle + one drug</strong>; reassess in 1 month"],
        ["Stage 1, no CVD, risk &lt;7.5%", "<strong>Lifestyle first</strong>; reassess in 3–6 months; add monotherapy if still above goal"],
        ["<strong>Stage 2 ≥140/≥90</strong>", "<strong>Lifestyle + two drugs</strong> (low-dose, ideally fixed-dose combination); reassess in 1 month"]
      ]) + "<p>Once on medication: if at goal, reassess every 3–6 months; if not, check adherence and intensify.</p>" + Tbl(["Lifestyle change", "Target", "≈ SBP drop"], [
        ["<strong>Weight loss</strong>", "BMI 18.5–24.9", "<strong>5–20 mmHg per 10 kg</strong> (largest)"],
        ["<strong>DASH diet</strong>", "Fruits, vegetables, whole grains, low-fat dairy; limit saturated fat and sugary drinks", "8–14 mmHg"],
        ["Exercise", "<strong>150 min/week</strong> of aerobic activity (≥30 min most days)", "4–9 mmHg"],
        ["Sodium restriction", "<strong>&lt;1500–2000 mg/day</strong>; consider salt substitute", "2–8 mmHg"],
        ["Alcohol moderation", "≤1 drink/day women and smaller men, ≤2 larger men (12 oz beer, 5 oz wine, 1.5 oz liquor)", "2–4 mmHg"],
        ["Tobacco cessation", "Cutting down beats continuing", "—"]
      ]) + "<p><strong>Chronic care visit:</strong> review office BP (oscillometric) and the home log (average, highest, lowest; ask about low-BP symptoms; validate the home cuff); ask about headache, vision change, epistaxis, dizziness, chest pain, dyspnea, edema; check adherence and side effects; exam; labs (chemistry, A1c, lipids); set <strong>one measurable lifestyle goal per visit</strong>; adjust the regimen.</p>" + Tbl(["Patient status", "Follow-up"], [
        ["Uncontrolled and noncompliant", "<strong>2–4 weeks</strong>"],
        ["Slightly uncontrolled, compliant", "3 months"],
        ["Controlled, compliant, with risk factors for progression", "3–6 months"],
        ["Chronically well controlled, compliant, otherwise healthy", "6 months"]
      ]) + HY("Stage 2 = start two drugs plus lifestyle right away. Stage 1 gets a drug immediately only with CVD, DM, CKD, or 10-year risk ≥7.5%.")),
      S("first-line-drugs", "First-Line Drugs: Thiazides, ACE Inhibitors, ARBs, CCBs", "<p>Without a compelling indication or contraindication, start with an <strong>ACEI or ARB, a CCB, or a thiazide-type diuretic</strong>. Stage 1 usually needs one agent; stage 2 needs two (combination lowers BP more, reaches goal faster, lowers dose-related side effects, and improves adherence). <strong>Never combine an ACEI with an ARB</strong> (ONTARGET: less proteinuria but worse renal outcomes). The common 3-drug regimen is ACEI/ARB + CCB + thiazide.</p>" + drugOverviewTable + Tbl(["Class", "Mechanism and key teaching points"], [
        ["<strong>Thiazides</strong>", "↑ renal Na excretion ± vasodilation. <strong>Chlorthalidone</strong> (longest acting) and <strong>indapamide</strong> have proven outcome benefit and 1.5–2× the BP effect of HCTZ (no outcome benefit shown for HCTZ). Give in the <strong>morning</strong>. Mild glucose rise → not preferred first line in DM (but usable). <strong>Chemistry panel in 5–7 days</strong> after starting or increasing (↓K, ↓Na). Weak alone; best with ACEI/ARB."],
        ["<strong>ACE inhibitors</strong>", "Block angiotensin I → II (less vasoconstriction and aldosterone) and <strong>↑ bradykinin</strong>. More effective in White than Black patients. Treatment of choice in <strong>CKD with proteinuria</strong>; reduce mortality in HFrEF and after MI. Check <strong>K and BUN/Cr in 5–10 days</strong>; a small creatinine rise is expected — <strong>stop for persistent hyperkalemia or a creatinine rise &gt;30%</strong>. Can worsen kidney function during hypovolemia (poor intake, N/V/D, GI bleed, overdiuresis)."],
        ["<strong>ACEI adverse effects</strong>", "<strong>Dry cough</strong> (1 week–6 months, can appear after years; more common in women; resolves on stopping). <strong>Hyperkalemia</strong> (CKD IV–V, DM, with an aldosterone antagonist). <strong>Angioedema</strong> — lips, tongue, pharynx; more common in Black and Asian patients; 50% in the first week; treat with diphenhydramine, methylprednisolone, famotidine, and airway protection; <strong>never prescribe another ACEI</strong>. <strong>Pregnancy: contraindicated (renal agenesis)</strong>."],
        ["<strong>ARBs</strong>", "Block angiotensin II at its receptor; efficacy similar to ACEI, better in White patients. <strong>Preferred over ACEI</strong> — less cough and angioedema; may be used (with caution) after ACEI angioedema and trialed after ACEI cough. Contraindicated in pregnancy. Chemistry panel in 5–7 days."],
        ["<strong>DHP CCBs</strong> (amlodipine, felodipine, nifedipine, IV nicardipine)", "Block vascular Ca channels → arteriolar vasodilation; <strong>heart-rate neutral</strong>. Flushing, dizziness, HA (10–20%); <strong>peripheral edema</strong> from ↑ vascular permeability — <strong>not diuretic-responsive</strong>, less common with a RAAS blocker, may require stopping the drug. Short-acting forms cause <strong>reflex tachycardia</strong>, so they are rarely used."]
      ]) + C("clinically used ARBs act selectively at the AT1 receptor (the slide says AT1 and AT2).") + "<p><strong>CCB overdose</strong> (5–10× dose): hypotension, <strong>bradycardia and PR prolongation</strong> (even with a DHP), and <strong>hyperglycemia</strong> (insulin release blocked). Mentation may stay clear until it suddenly deteriorates — recheck neuro status often. Treat with IV fluids, atropine (may fail), activated charcoal, <strong>IV calcium</strong>, glucagon, norepinephrine, and <strong>high-dose insulin</strong>.</p>" + HY("ACEI cough → switch to an ARB. ACEI angioedema → never another ACEI; an ARB may be used cautiously. Never ACEI + ARB together.")),
      S("other-diuretics", "Loop and Potassium-Sparing Diuretics", Tbl(["Class", "Key points"], [
        ["<strong>Loop diuretics</strong> (furosemide, bumetanide, torsemide; ethacrynic acid)", "Act in the <strong>thick ascending limb</strong>; mainly for <strong>edema (HF, ascites, CKD)</strong>, not HTN — but their BP effect counts in the regimen. Sulfonamides except <strong>ethacrynic acid</strong> (for severe sulfa allergy). Furosemide 40 = bumetanide 1 = torsemide 20 mg; IV furosemide ≈ 2× oral. Higher doses in low GFR; IV in acute decompensated HF or bowel edema. Usually given with <strong>K supplement</strong> (~20 mEq per 40 mg furosemide); dose AM, last dose by 5 pm. Adverse: ↓K, ↓Na, hypovolemia with <strong>contraction alkalosis</strong>, gout, rash/interstitial nephritis, <strong>ototoxicity</strong> at high doses."],
        ["<strong>ENaC blockers</strong> (triamterene — paired with HCTZ; amiloride)", "Block distal tubule Na channels: weak diuresis, <strong>K conserved</strong>. Amiloride is better tolerated and less nephrotoxic. Adverse: <strong>hyperkalemia</strong> (DM, CKD, ACEI/ARB); triamterene <strong>crystalluria/casts → stones, AKI</strong>."]
      ]) + HY("Loop diuretic side effect unique among the diuretics taught: ototoxicity (tinnitus, hearing loss) at high doses."))
    ], [
      Q("epidemiology", "Which region has the highest prevalence of hypertension worldwide?", ["Africa", "The Americas", "Europe", "Southeast Asia"], 0, "Africa has the highest global prevalence (27%) and the Americas the lowest (18%)."),
      Q("epidemiology", "About what fraction of US adults with hypertension have it under control?", ["About 1 in 4", "About 3 in 4", "About 1 in 2", "About 1 in 10"], 0, "Only about 1 of every 4 US adults with hypertension is controlled; control is highest in White (32%) and lowest in Asian (19%) patients."),
      Q("epidemiology", "Controlling BP to goal produces the largest relative reduction in which outcome?", ["Heart failure (~50%)", "MI (~20–25%)", "Stroke (~10%)", "Overall mortality (~40%)"], 0, "BP control reduces heart failure ~50%, stroke 30–40%, MI 20–25%, and overall mortality 11%."),
      Q("epidemiology", "Starting from 115/75, how much does CVD risk change with each 20/10 mmHg increase in BP?", ["It doubles", "It rises by 10%", "It triples", "It does not change until 140/90"], 0, "CVD risk doubles for every 20/10 increment above 115/75, the level with the lowest risk."),
      Q("physiology", "Which formula correctly estimates mean arterial pressure?", ["[(2 × DBP) + SBP] / 3", "(SBP + DBP) / 2", "[(2 × SBP) + DBP] / 3", "SBP − DBP"], 0, "MAP = [(2 × DBP) + SBP] / 3 because diastole occupies about two-thirds of the cardiac cycle. A MAP of 70–100 is adequate."),
      Q("physiology", "A sudden rise in BP stretches the carotid sinus. What is the immediate reflex response?", ["Sympathetic outflow falls and parasympathetic tone rises", "Renin release increases", "Sympathetic outflow rises and heart rate increases", "ADH secretion increases"], 0, "Increased baroreceptor firing to the medullary cardiovascular center inhibits sympathetic and activates parasympathetic output — the short-term neural control of BP."),
      Q("physiology", "Which is NOT one of the three triggers for renin release taught in the lecture?", ["High sodium delivery to the macula densa", "Renal sympathetic NE acting on β1 receptors of juxtaglomerular cells", "Low afferent arteriolar pressure sensed by juxtaglomerular cells", "Low sodium sensed by the macula densa"], 0, "Renin is released by sympathetic β1 stimulation, low afferent arteriole pressure, or LOW sodium at the macula densa. High sodium suppresses renin."),
      Q("pathophysiology", "What proportion of hypertension is primary (essential)?", ["90–95%", "50–60%", "75%", "99%"], 0, "Primary hypertension accounts for 90–95% of cases; secondary causes make up the remaining ~5%."),
      Q("pathophysiology", "How does obesity raise blood pressure, according to the lecture?", ["Increases intravascular volume, cardiac output, sympathetic outflow, and RAAS activity", "Decreases cardiac output through reduced preload", "Causes polycythemia that raises viscosity", "Suppresses renin and aldosterone"], 0, "Obesity expands volume, raises CO, increases sympathetic outflow, and activates the renin–angiotensin system; weight loss lowers BP."),
      Q("pathophysiology", "Which is a non-modifiable risk factor for primary hypertension?", ["African American race", "Sleeping fewer than 7 hours nightly", "Low-potassium diet", "Alcohol over 2 drinks a day"], 0, "Race, family history, male sex, age, psychosocial stress, and low socioeconomic status are listed as non-modifiable. Sleep, diet, and alcohol are modifiable."),
      Q("pathophysiology", "Compared with White patients, African American patients develop hypertension:", ["About 10 years earlier, with more severe disease and more complications", "About 10 years later, with milder disease", "At the same age but with fewer complications", "Only after age 65"], 0, "On average African Americans develop HTN about 10 years earlier, with more severe BP elevations and more complications."),
      Q("pathophysiology", "Smoking raises blood pressure mainly by:", ["Increasing plasma norepinephrine", "Increasing sodium retention through aldosterone", "Causing polycythemia", "Suppressing ANP"], 0, "Smoking increases plasma norepinephrine, and smoking plus HTN have a synergistic effect on CV risk."),
      Q("diagnosis", "A 45-year-old has an average BP of 136/78 on repeated readings. How is this classified?", ["Stage 1 hypertension", "Elevated BP", "Stage 2 hypertension", "Normal BP"], 0, "Systolic 130–139 OR diastolic 80–89 is stage 1. A systolic of 136 is enough even though the diastolic is under 80 (this is also isolated systolic HTN)."),
      Q("diagnosis", "A patient’s average BP is 128/92. What is the stage?", ["Stage 2 hypertension", "Elevated BP", "Stage 1 hypertension", "Isolated systolic hypertension"], 0, "When systolic and diastolic fall in different categories, the higher one sets the stage. A diastolic ≥90 is stage 2."),
      Q("diagnosis", "Which BP is classified as elevated BP?", ["124/76", "118/78", "132/76", "126/82"], 0, "Elevated BP is systolic 120–129 AND diastolic below 80. 126/82 is stage 1 because of the diastolic."),
      Q("diagnosis", "In which situation may hypertension be diagnosed at a single visit?", ["Initial BP 164/102 in a patient with known left ventricular hypertrophy", "Initial BP 150/95 in an asymptomatic 40-year-old", "Initial BP 138/88 with a family history of HTN", "Initial BP 145/92 after drinking coffee"], 0, "A single-visit diagnosis is allowed only for BP ≥180/≥120, or ≥160/≥100 with known target-organ damage such as LVH, CAD, HF, stroke, retinopathy, or CKD."),
      Q("diagnosis", "What are the standard clinical criteria for diagnosing hypertension?", ["The average of ≥2 seated readings 1–2 minutes apart on ≥2 separate visits, preferably confirmed out of office", "One reading ≥130/80 at any visit", "Three readings at one visit averaged together", "A single 24-hour urine sodium measurement"], 0, "HTN is diagnosed from the average of two or more readings on two or more visits; out-of-office monitoring (ABPM preferred) confirms it."),
      Q("diagnosis", "Office BP averages 138/86, but daytime ambulatory BP averages 122/74. What is the diagnosis?", ["White coat hypertension", "Stage 1 hypertension", "Masked hypertension", "Isolated diastolic hypertension"], 0, "Elevated office readings with out-of-office readings below 130/80 is white coat hypertension; reassess periodically for development of true HTN."),
      Q("diagnosis", "A 28-year-old with no risk factors has a normal BP. How often should BP be screened?", ["Every 3–5 years", "Annually", "Every 6 months", "Every 10 years"], 0, "Adults 18–39 with normal BP and no risk factors are screened every 3–5 years; age ≥40 or risk factors means annual screening."),
      Q("measurement", "Which technique error raises measured BP the most?", ["Talking during the measurement", "Back not supported", "Cuff slightly too large", "Not resting for 5 minutes"], 0, "Talking raises BP about 17/13 mmHg — the largest error listed. No rest adds 12/6, an unsupported back 6/8, and a too-large cuff about 7/5."),
      Q("measurement", "If the patient’s arm hangs at the side instead of being supported at heart level, the BP reading will be:", ["Falsely high by about 10–12 mmHg", "Falsely low by about 10–12 mmHg", "Unchanged", "Falsely high by about 30 mmHg"], 0, "Below heart level, added hydrostatic pressure raises the reading by about 10–12 mmHg."),
      Q("measurement", "Which method is preferred for diagnosing hypertension and white coat hypertension?", ["Ambulatory BP monitoring", "A single automated office reading", "Home BP monitoring with a wrist cuff", "Manual office reading by the physician"], 0, "ABPM is preferred for diagnosis, better predicts target-organ damage and CV events, and is the only method that reliably captures nocturnal BP."),
      Q("measurement", "A patient’s BP does not fall at night on ambulatory monitoring. What does this mean?", ["He is a non-dipper, which adds cardiovascular risk", "This is a normal finding", "The device is malfunctioning", "He has white coat hypertension"], 0, "BP normally falls during sleep; non-dippers carry additional CV risk, and this is readily detected only with ABPM."),
      Q("measurement", "A patient’s arm circumference is 38 cm. Which cuff is correct?", ["Large adult", "Adult", "Small adult", "Adult thigh"], 0, "22–26 cm small adult, 27–34 adult, 35–44 large adult, 45–52 adult thigh. A cuff that is too small falsely raises BP."),
      Q("measurement", "How should a patient perform home BP monitoring after a medication change?", ["Twice each morning before meds and each evening before dinner, readings 1 minute apart, for 2 weeks", "Once a day at any time for 3 days", "Only when symptomatic", "Every hour while awake for 1 week"], 0, "HBPM: seated after ≥5 min rest, two readings 1 minute apart morning and evening, for 2 weeks after a medication change or 1 week before a visit."),
      Q("evaluation", "Which exam finding suggests coarctation of the aorta in a newly hypertensive patient?", ["Delay of the femoral pulse compared with the radial pulse", "Weak pedal pulses with hair loss", "An S4 gallop", "AV nicking on fundoscopy"], 0, "A radial–femoral delay points to coarctation. Weak pedal pulses suggest PAD; S4 and AV nicking reflect target-organ damage."),
      Q("evaluation", "Which test is part of the baseline evaluation of every new hypertensive patient to look for left ventricular hypertrophy?", ["12-lead ECG", "Coronary angiography", "Exercise stress test", "Renal angiogram"], 0, "A baseline ECG screens for LVH; an echo is considered if the ECG is abnormal."),
      Q("evaluation", "Which lab is NOT part of the lecture’s routine initial work-up for new hypertension?", ["24-hour urine metanephrines", "TSH", "Urinalysis for protein", "Fasting lipid panel"], 0, "Routine labs: UA, glucose/A1c, CBC, electrolytes with creatinine and calcium, TSH, fasting lipids, and ECG. Metanephrines are reserved for suspected pheochromocytoma."),
      Q("evaluation", "Which fundoscopic finding reflects hypertensive retinopathy?", ["AV nicking", "Cherry-red spot", "Neovascularization of the iris", "Drusen"], 0, "Cotton wool spots, AV nicking, arteriolar narrowing, hemorrhages, exudates, and papilledema are the HTN eye findings taught."),
      Q("treatment-approach", "What BP goal does the ACC/AHA guideline set for patients treated for hypertension?", ["<130/80", "<140/90", "<150/90", "<120/70"], 0, "The ACC/AHA goal for treated patients is below 130/80."),
      Q("treatment-approach", "A 52-year-old with average BP 146/94 and no other conditions. What is the initial plan?", ["Lifestyle changes plus two antihypertensives, ideally a fixed-dose combination", "Lifestyle changes alone and recheck in 6 months", "A single beta-blocker", "Lifestyle changes plus an ACEI and an ARB"], 0, "Stage 2 HTN: start lifestyle therapy plus two drugs (low dose, fixed-dose combination when possible) and reassess in 1 month. ACEI + ARB is never combined."),
      Q("treatment-approach", "A 50-year-old with average BP 134/82, no CVD, DM, or CKD, and a 10-year PREVENT risk of 4%. What is the initial plan?", ["Lifestyle changes alone, then reassess in 3–6 months", "Lifestyle plus a thiazide now", "Lifestyle plus two drugs now", "No intervention and recheck in 5 years"], 0, "Stage 1 with risk <7.5% and no CVD, DM, or CKD starts with lifestyle; add monotherapy if still above goal at reassessment."),
      Q("treatment-approach", "A 58-year-old with type 2 diabetes has an average BP of 134/84. What is the initial plan?", ["Lifestyle changes plus one antihypertensive, reassess in 1 month", "Lifestyle changes alone for 6 months", "Two-drug combination therapy", "Observation without treatment"], 0, "Stage 1 HTN with DM, CKD, CVD, or 10-year risk ≥7.5% gets lifestyle plus monotherapy right away, with reassessment in 1 month."),
      Q("treatment-approach", "Which lifestyle change produces the largest SBP reduction?", ["Weight loss (5–20 mmHg per 10 kg)", "Alcohol moderation", "Sodium restriction", "Aerobic exercise"], 0, "Weight loss lowers SBP 5–20 mmHg per 10 kg; DASH 8–14, exercise 4–9, sodium 2–8, and alcohol moderation 2–4 mmHg."),
      Q("treatment-approach", "What is the lecture’s physical activity goal for patients with hypertension?", ["150 minutes per week in divided sessions", "30 minutes once a week", "300 minutes per week of resistance training only", "60 minutes per day of vigorous exercise"], 0, "The goal is 150 minutes/week of physical activity in divided sessions (≥30 minutes most days)."),
      Q("treatment-approach", "A hypertensive patient is uncontrolled and admits he has not been taking his medication. When should he return?", ["In 2–4 weeks", "In 3 months", "In 6 months", "In 1 year"], 0, "Uncontrolled and noncompliant: 2–4 weeks. Slightly uncontrolled but compliant: 3 months. Controlled with risk factors: 3–6 months. Well controlled and healthy: 6 months."),
      Q("first-line-drugs", "Without a compelling indication, which group lists the first-line antihypertensive classes?", ["ACEI or ARB, CCB, thiazide-type diuretic", "Beta-blocker, loop diuretic, CCB", "Alpha-1 blocker, ACEI, hydralazine", "Clonidine, thiazide, spironolactone"], 0, "First line is an ACEI or ARB, a calcium channel blocker, or a thiazide-type diuretic. Beta-blockers, alpha-blockers, central agents, aldosterone antagonists, and vasodilators are later-line."),
      Q("first-line-drugs", "Which thiazide-type diuretics have the best-established outcome benefit and BP-lowering efficacy?", ["Chlorthalidone and indapamide", "Hydrochlorothiazide and metolazone", "Furosemide and torsemide", "Triamterene and amiloride"], 0, "Chlorthalidone and indapamide reduce strokes and major CV events and lower BP 1.5–2× more than HCTZ, for which no outcome benefit has been shown."),
      Q("first-line-drugs", "Which electrolyte change is characteristic of thiazides but not loop diuretics?", ["Hypercalcemia", "Hypokalemia", "Hyponatremia", "Hyperuricemia"], 0, "Both cause hypokalemia, hyponatremia, and hyperuricemia; thiazides also raise calcium."),
      Q("first-line-drugs", "Three months after starting lisinopril, a woman develops a persistent dry cough. What is the best change?", ["Switch to an ARB", "Add an ARB to the lisinopril", "Switch to a different ACE inhibitor", "Add a cough suppressant and continue"], 0, "ACEI cough resolves when the drug is stopped. An ARB can be trialed (stop it if a persistent cough occurs). ACEI + ARB is never combined."),
      Q("first-line-drugs", "A patient on an ACE inhibitor develops sudden swelling of the lips and tongue. After airway protection, what is the long-term plan?", ["Stop the drug and never prescribe another ACE inhibitor", "Switch to a different ACE inhibitor", "Continue at half the dose", "Resume the ACE inhibitor with diphenhydramine pretreatment"], 0, "ACEI angioedema is life-threatening: treat with diphenhydramine, methylprednisolone, famotidine, and airway protection; stop the drug and never use another ACEI. An ARB may be used with caution and education."),
      Q("first-line-drugs", "One week after starting an ACE inhibitor, creatinine has risen 40% from baseline. What should be done?", ["Stop the ACE inhibitor", "Continue; this is the expected small rise", "Double the dose", "Add an ARB"], 0, "A small temporary creatinine rise is expected, but a rise >30% or persistent hyperkalemia requires stopping the drug — and should raise suspicion for renal artery stenosis."),
      Q("first-line-drugs", "Why are ACE inhibitors and ARBs contraindicated in pregnancy?", ["Risk of fetal renal agenesis", "Risk of neural tube defects", "Risk of maternal angioedema", "Risk of fetal bradycardia"], 0, "Both are teratogenic (category X for ACEI) because of the risk of renal agenesis in the fetus."),
      Q("first-line-drugs", "A patient started on amlodipine develops ankle edema. Which statement is true?", ["It comes from increased vascular permeability and usually does not respond to diuretics", "It means volume overload, so a loop diuretic will fix it", "It indicates new heart failure", "It is more common when amlodipine is paired with an ACE inhibitor"], 0, "DHP CCB edema comes from vascular permeability, not plasma volume, so diuretics rarely help; it is less common with a RAAS blocker and may require stopping the CCB."),
      Q("first-line-drugs", "Why are short-acting DHP calcium channel blockers rarely used?", ["The sudden drop in BP causes reflex tachycardia", "They cause severe bradycardia", "They cause hyperkalemia", "They cause angioedema"], 0, "Short-acting forms drop BP suddenly and trigger baroreceptor-mediated reflex tachycardia."),
      Q("first-line-drugs", "A patient took 30 tablets of amlodipine. He is hypotensive with a PR of 280 ms and glucose of 260 but is talking normally. Which statement is correct?", ["His mental status can deteriorate suddenly, so recheck neuro status frequently", "Clear mentation rules out a serious overdose", "Hyperglycemia means he also took a sulfonylurea", "DHP CCBs do not affect the AV node, so the PR is unrelated"], 0, "CCB overdose causes hypotension, bradycardia, PR prolongation (even with a DHP), and hyperglycemia; mentation may stay clear until cerebral perfusion becomes critical."),
      Q("first-line-drugs", "Which treatments are used for calcium channel blocker overdose?", ["IV fluids, atropine, IV calcium, glucagon, vasopressors, and high-dose insulin", "Naloxone and flumazenil", "Lipid emulsion only", "Physostigmine and benzodiazepines"], 0, "Give IV fluids and atropine first, then activated charcoal, IV calcium, glucagon, norepinephrine, and high-dose insulin as needed."),
      Q("other-diuretics", "A patient with severe sulfa allergy needs a loop diuretic. Which drug is appropriate?", ["Ethacrynic acid", "Furosemide", "Bumetanide", "Torsemide"], 0, "Furosemide, bumetanide, and torsemide are sulfonamide derivatives; ethacrynic acid is the non-sulfa loop."),
      Q("other-diuretics", "Which adverse effect is specific to loop diuretics among the diuretics taught?", ["Ototoxicity (tinnitus and hearing loss)", "Hypokalemia", "Gout", "Hypovolemia"], 0, "Loops cause hypokalemia, hyponatremia, overdiuresis with contraction alkalosis, and gout like thiazides, but high doses can also cause ototoxicity."),
      Q("other-diuretics", "Which potassium-sparing diuretic causes crystalluria and casts that can lead to kidney stones and AKI?", ["Triamterene", "Amiloride", "Eplerenone", "Spironolactone"], 0, "Triamterene causes crystalluria and cast formation; amiloride is better tolerated and less nephrotoxic.")
    ]),

    // ------------------------------------------------------------------
    D("htn-target-organ-damage", "Hypertensive Target-Organ Damage (Heart, Brain, Kidney)", "Complicated hypertension: years of high afterload stiffen arteries, thicken the left ventricle (LVH → HFpEF → HFrEF), and reset cerebral and renal autoregulation. Look for an S4, displaced apex, LVH on ECG, retinopathy, and CKD.", [
      S("natural-history", "Natural History and Vascular Remodeling", Tbl(["Phase", "What is happening"], [
        ["Prehypertension", "Asymptomatic ↑ cardiac output; intermittently elevated BP"],
        ["Early HTN", "Persistently ↑ peripheral resistance"],
        ["Established HTN", "Vascular remodeling; progressive damage"],
        ["<strong>Complicated HTN</strong>", "<strong>End-organ damage</strong>"]
      ]) + "<p><strong>Vascular remodeling:</strong> chronic HTN ↑ afterload → <strong>stiffer, less compliant arteries</strong> → higher systolic BP and a <strong>wider pulse pressure</strong>.</p><p><strong>Complications:</strong> CKD progression, LVH, HF (systolic and diastolic), ischemic stroke, intracerebral hemorrhage, ischemic heart disease, and hypertensive retinopathy.</p>" + HY("Stiff arteries = high systolic, normal-to-low diastolic, wide pulse pressure — the isolated systolic HTN of older adults.")),
      S("heart", "Hypertensive Heart Disease", "<p>High afterload <strong>reduces coronary perfusion</strong> to an overworked myocardium and <strong>raises myocardial O2 demand</strong> → myocytes hypertrophy (<strong>LVH</strong>) so the heart can pump against high aortic pressure.</p><ol><li><strong>Diastolic dysfunction comes first</strong>: the stiff, thick LV relaxes incompletely → ↑ LVEDP → ↑ left atrial pressure (<strong>HFpEF</strong>, LA enlargement)</li><li>LVH encroaches on the cavity → limits filling and stroke volume</li><li>Long-preserved systolic function fails → <strong>HFrEF</strong></li><li>Aortic root dilation and valve incompetence, atrial and ventricular arrhythmias, ischemic heart disease/cardiomyopathy</li></ol><p>LVH is associated with an increased risk of premature death. Exam: heave, <strong>displaced apical impulse, S4</strong>, rales. Tests: ECG (LVH), echo (diastolic/systolic dysfunction, wall motion).</p>" + HY("In hypertensive heart disease, diastolic dysfunction (HFpEF) appears before systolic failure (HFrEF).")),
      S("brain", "The Brain: Cerebral Autoregulation", "<p><strong>Cerebral autoregulation</strong> keeps cerebral blood flow constant across a <strong>MAP of about 60–150 mmHg</strong>: arterioles dilate when BP falls and constrict when BP rises. <strong>CPP = MAP − ICP</strong>.</p><ul><li>In a normotensive or mildly hypertensive patient, a <strong>rapid BP rise</strong> can cause hyperperfusion, ↑ ICP, cerebral edema, carotid/cerebral dissection, ischemic or hemorrhagic stroke.</li><li>With <strong>chronic HTN</strong>, the brain adapts to high pressures (↑ cerebral vascular resistance; the curve shifts right) — so dropping BP quickly into the normal range causes <strong>cerebral ischemia</strong>.</li><li>Therefore lower BP in long-standing HTN <strong>gradually over a few weeks</strong> so autoregulation can reset.</li></ul><p>Chronic damage: headaches, cerebral atrophy greater than expected for age, dementia (vascular/Alzheimer’s risk 2–4×).</p>" + HY("For long-standing HTN, lowering BP too fast is as dangerous as leaving it high — titrate over weeks.")),
      S("kidney", "The Kidney", "<p>Chronic HTN causes <strong>sclerosis of small renal arteries</strong> → endothelial dysfunction and impaired vasodilation → <strong>loss of renal autoregulation</strong>, so intraglomerular pressure varies directly with systemic BP and the glomerulus is unprotected from BP swings.</p><ul><li><strong>Glomerular disease</strong> (nephrotic/nephritic): HTN driven mainly by <strong>volume expansion</strong></li><li><strong>Renal vascular disease (RAS)</strong>: near-constant <strong>RAAS activation</strong> from ischemia</li><li><strong>Chronic renal failure</strong>: volume expansion + RAAS activation together</li></ul><p>Black patients are <strong>4×</strong> as likely to develop renal complications and ESKD from HTN. Detect with creatinine/eGFR and urine protein (microalbuminuria).</p>" + HY("Once renal autoregulation is lost, every BP swing is transmitted straight to the glomerulus.")),
      S("detection", "Finding Target-Organ Damage", Tbl(["Organ", "History", "Exam / tests"], [
        ["Heart", "Chest pain, dyspnea, fatigue, leg swelling", "S4, heave, displaced apex; ECG/echo for LVH, diastolic or systolic dysfunction"],
        ["Brain", "Headaches, TIA/stroke, cognitive decline", "Neuro exam; atrophy on CT/MRI"],
        ["Kidney", "Oliguria, hematuria, flank pain", "Creatinine/eGFR, urine protein"],
        ["Vessels", "Extremity pain, hair loss, cool pale limbs", "Pulses, bruits (PAD)"],
        ["Eye", "Visual change", "Cotton wool spots, AV nicking, arteriolar narrowing, hemorrhages, exudates, papilledema"]
      ]) + "<p>Known target-organ damage lowers the single-visit diagnostic threshold to <strong>≥160/≥100</strong>.</p>")
    ], [
      Q("natural-history", "What happens to the arteries with chronic uncontrolled hypertension?", ["They stiffen, raising systolic BP and widening pulse pressure", "They become more compliant, lowering systolic BP", "They dilate, lowering diastolic BP only", "They are unaffected until hypertensive emergency"], 0, "Chronic HTN increases arterial wall stiffness (less compliance), raising systolic BP and widening pulse pressure."),
      Q("natural-history", "Which stage of the natural history of hypertension is defined by end-organ damage?", ["Complicated hypertension", "Prehypertension", "Early hypertension", "Established hypertension"], 0, "Prehypertension: ↑ CO; early: ↑ peripheral resistance; established: vascular remodeling; complicated: end-organ damage."),
      Q("heart", "Which cardiac abnormality appears first in hypertensive heart disease?", ["Diastolic dysfunction from a stiff, hypertrophied LV", "Systolic dysfunction with low ejection fraction", "Aortic root dilation", "Ventricular tachycardia"], 0, "The thick LV relaxes incompletely, raising LVEDP — diastolic dysfunction (HFpEF) comes before systolic failure."),
      Q("heart", "Why does the left ventricle hypertrophy in chronic hypertension?", ["To pump against persistently high afterload", "Because preload is chronically low", "Because coronary blood flow is increased", "Because of right ventricular failure"], 0, "Increased afterload raises O2 demand and lowers coronary perfusion; myocytes hypertrophy so the LV can pump against the high aortic pressure."),
      Q("heart", "A 64-year-old with long-standing HTN has a laterally displaced apical impulse and an S4. What do these findings suggest?", ["Left ventricular hypertrophy from hypertensive heart disease", "Coarctation of the aorta", "Pheochromocytoma", "Primary hyperaldosteronism"], 0, "A heave, displaced apex, and S4 reflect a stiff, hypertrophied LV — target-organ damage in the heart."),
      Q("heart", "As LVH progresses, how does it eventually cause systolic failure?", ["The thickened wall encroaches on the cavity, limiting filling and stroke volume", "It causes mitral stenosis", "It lowers afterload", "It increases coronary perfusion pressure"], 0, "LVH impinges on the cavity, limiting diastolic filling and stroke volume until the long-preserved systolic function fails (HFrEF)."),
      Q("brain", "Over what MAP range does cerebral autoregulation keep cerebral blood flow constant?", ["About 60–150 mmHg", "About 20–60 mmHg", "About 150–250 mmHg", "About 100–120 mmHg only"], 0, "Cerebral flow is constant across a MAP of about 60–150 mmHg; chronic HTN shifts this range upward."),
      Q("brain", "A patient with long-standing BP around 180/105 is started on three drugs and is 118/70 two days later, now confused and dizzy. What explains this?", ["Cerebral hypoperfusion — autoregulation had reset to higher pressures", "Hypertensive encephalopathy from hyperperfusion", "Drug-induced lupus", "White coat effect"], 0, "Chronic HTN raises cerebral vascular resistance; rapid lowering into the normal range causes ischemia. Lower BP gradually over weeks."),
      Q("brain", "Which equation describes cerebral perfusion pressure?", ["CPP = MAP − ICP", "CPP = ICP − MAP", "CPP = CO × TPR", "CPP = SBP − DBP"], 0, "Cerebral perfusion pressure equals mean arterial pressure minus intracranial pressure."),
      Q("kidney", "What happens to renal autoregulation in chronic hypertension?", ["It is disrupted, so intraglomerular pressure varies directly with systemic BP", "It becomes more efficient, protecting the glomerulus", "It is unaffected because the kidney has its own blood supply", "It only fails during hypotension"], 0, "Sclerosis of small renal arteries impairs vasodilation and autoregulation, leaving the glomerulus unprotected during BP swings."),
      Q("kidney", "In a patient with nephrotic or nephritic syndrome, what mainly drives the hypertension?", ["Volume expansion", "Renin-secreting tumor", "Catecholamine excess", "Sympathetic overactivity from hypoxia"], 0, "Volume expansion drives HTN in glomerular disease; RAAS activation drives it in renal vascular disease; both combine in chronic renal failure."),
      Q("kidney", "Compared with White patients, how much more likely are Black patients to develop ESKD from hypertension?", ["About 4 times", "About 1.3 times", "About 10 times", "No difference"], 0, "Black patients are 4 times as likely to have renal complications and ESKD from HTN, with 1.3× nonfatal and 1.8× fatal stroke risk."),
      Q("detection", "Which finding is an eye manifestation of hypertensive target-organ damage?", ["Arteriolar narrowing with cotton wool spots", "Lens dislocation", "Kayser–Fleischer rings", "Roth spots"], 0, "Hypertensive retinopathy shows cotton wool spots, AV nicking, arteriolar narrowing, hemorrhages, exudates, and papilledema.")
    ]),

    // ------------------------------------------------------------------
    D("htn-secondary", "Secondary Hypertension: When to Suspect It (and PCKD, Thyroid, Cushing’s)", "About 5% of hypertension has an identifiable cause. Suspect it with onset before 20–25 or after 50, BP resistant to 3–4 drugs, or a telltale clue such as hypokalemia, a bruit, unequal arm pressures, or episodic palpitations.", [
      S("overview", "When to Suspect and Screen", "<p>Secondary HTN is <strong>~5%</strong> of cases but accounts for about <strong>20% of resistant HTN</strong>. It is often found in patients diagnosed <strong>before age 20 or after 50</strong>. Testing is expensive, so screen only with clinical suspicion:</p><ul><li><strong>New HTN before age 20–25</strong> (can be younger in Black patients)</li><li><strong>HTN refractory to medical therapy (&gt;3–4 drugs)</strong></li><li><strong>Specific clinical/lab features</strong>: persistent hypokalemia, epigastric/abdominal bruit, different BP between arms, episodic HTN with flushing or palpitations</li></ul>" + Tbl(["Group", "Causes taught"], [
        ["Congenital", "Polycystic kidney disease, coarctation of the aorta"],
        ["Acquired", "Renal artery stenosis, OSA, medications/substances"],
        ["Endocrine", "Hyperaldosteronism, Cushing’s, pheochromocytoma, thyroid disease"]
      ]) + secondaryCluesTable + Mn("Secondary causes: “CHAMPS-OT”", "Coarctation, Hyperaldosteronism, Atherosclerotic/FMD renal artery stenosis, Medications, Polycystic kidneys, Sleep apnea, ...Other endocrine (Cushing’s, pheo), Thyroid.")),
      S("pckd", "Polycystic Kidney Disease", "<p><strong>Autosomal dominant</strong>. Kidneys progressively enlarge (up to 5× normal) from growing cysts. Patients have <strong>flank pain, hematuria, UTIs, renal calculi</strong>, and difficulty concentrating urine, plus HTN.</p>"),
      S("thyroid", "Thyroid Disease", "<p><strong>Either hypo- or hyperthyroidism</strong> can raise BP. Clues: cold or heat intolerance, sweating, low energy, bradycardia or tachycardia. <strong>Screen with a TSH</strong> (part of every new-HTN work-up). Hypothyroidism is very common, but HTN caused by it is relatively uncommon.</p>"),
      S("cushing", "Cushing’s Syndrome", "<p>Glucocorticoid excess from a <strong>pituitary ACTH-secreting adenoma</strong>, an <strong>autonomous adrenal adenoma/hyperplasia</strong>, or an <strong>ectopic ACTH source (usually small cell lung cancer)</strong>. Excess cortisol causes <strong>Na and water retention</strong> → volume expansion, with a mild aldosterone rise.</p>" + C("screening tests for Cushing’s syndrome include a 24-hour urine free cortisol, late-night salivary cortisol, or 1-mg overnight dexamethasone suppression test (not on the slides)."))
    ], [
      Q("overview", "About what percentage of resistant hypertension is due to secondary causes?", ["About 20%", "About 5%", "About 50%", "About 90%"], 0, "Secondary HTN is ~5% of all HTN but about 20% of resistant HTN."),
      Q("overview", "Which patient most warrants screening for secondary hypertension?", ["An 19-year-old with newly diagnosed hypertension", "A 48-year-old with stage 1 HTN controlled on one drug", "A 55-year-old with obesity and elevated BP", "A 62-year-old with white coat hypertension"], 0, "Screen with new HTN before about age 20–25, HTN refractory to more than 3–4 drugs, or specific suggestive features."),
      Q("overview", "Which finding is a specific clue that should prompt evaluation for secondary hypertension?", ["Persistent unprovoked hypokalemia", "A BMI of 31", "A family history of hypertension", "Elevated LDL"], 0, "Persistent hypokalemia, abdominal bruits, different BP in the two arms, and episodic HTN with flushing or palpitations are specific features."),
      Q("overview", "Which secondary causes does the lecture classify as congenital?", ["Polycystic kidney disease and coarctation of the aorta", "Renal artery stenosis and OSA", "Pheochromocytoma and Cushing’s", "Thyroid disease and hyperaldosteronism"], 0, "Congenital: PCKD and coarctation. Acquired: RAS, OSA, medications. Endocrine: hyperaldosteronism, Cushing’s, pheochromocytoma, thyroid."),
      Q("pckd", "A 36-year-old with hypertension has flank pain, hematuria, recurrent kidney stones, and large palpable kidneys; his mother had dialysis. What is the likely cause?", ["Autosomal dominant polycystic kidney disease", "Fibromuscular dysplasia", "Primary hyperaldosteronism", "Coarctation of the aorta"], 0, "PCKD is autosomal dominant: enlarging cystic kidneys with flank pain, hematuria, UTI, stones, and poor urine concentration."),
      Q("thyroid", "Which test screens for thyroid disease as a cause of hypertension?", ["TSH", "Free T3 alone", "Thyroid ultrasound", "Radioactive iodine uptake"], 0, "Either hypo- or hyperthyroidism can cause HTN; screen with a TSH."),
      Q("thyroid", "Which statement about hypothyroidism and hypertension is correct?", ["Hypothyroidism is very common, but HTN caused by it is relatively uncommon", "Hypothyroidism is the most common secondary cause of HTN", "Only hyperthyroidism raises BP", "Hypothyroidism lowers BP and never causes HTN"], 0, "The lecture notes hypothyroidism is common, but HTN due to it is relatively uncommon; both hypo- and hyperthyroidism can raise BP."),
      Q("cushing", "How does Cushing’s syndrome raise blood pressure?", ["Glucocorticoid excess causes Na and water retention and volume expansion", "Catecholamine surges cause vasoconstriction", "Renin is secreted by a tumor", "Hypoxia activates the sympathetic system"], 0, "Excess glucocorticoid retains Na and water, expanding volume, with a mild aldosterone increase."),
      Q("cushing", "Which tumor most often causes ectopic ACTH secretion leading to Cushing’s syndrome?", ["Small cell lung cancer", "Pheochromocytoma", "Renal cell carcinoma", "Papillary thyroid cancer"], 0, "Paraneoplastic (ectopic) ACTH most often comes from small cell lung cancer.")
    ]),

    // ------------------------------------------------------------------
    D("htn-renovascular", "Renovascular Hypertension (Renal Artery Stenosis)", "A narrowed renal artery makes the under-perfused kidney drive RAAS nonstop. Think of it with AKI after starting an ACEI/ARB, refractory HTN in an older smoker with vascular disease, flash pulmonary edema, or an abdominal bruit — or a young woman with fibromuscular dysplasia.", [
      S("pathophysiology", "Definition and Pathophysiology", "<p><strong>Renovascular HTN</strong> is hypertension caused by <strong>renal artery stenosis</strong>. The kidney with low blood flow keeps the <strong>renin–angiotensin–aldosterone system constantly activated</strong> → angiotensin II (intense arteriolar vasoconstriction) and aldosterone (volume expansion) → high BP.</p><p>Raising volume and BP does <strong>not</strong> fix the poorly perfused kidney because the stenosis is a <strong>fixed obstruction</strong> — so RAAS stays on. The constant high BP raises cardiac work, remodels the heart and vessels, and damages the <strong>normal contralateral kidney</strong> with high vascular pressures.</p>" + HY("RAS is a renin-high state: the kidney behind the stenosis “sees” low pressure no matter how high systemic BP climbs.")),
      S("populations", "Two Populations", Tbl(["", "Atherosclerotic RAS", "Fibromuscular dysplasia (FMD)"], [
        ["Who", "<strong>Men &gt;50</strong> with CAD risk factors: HLD, tobacco, DM, CKD, PAD", "<strong>Women &lt;50</strong>"],
        ["Imaging", "Ostial/proximal stenosis", "<strong>“String of beads / pearls”</strong> on imaging; aneurysms may coexist"],
        ["Intervention shown", "<strong>Stent</strong>", "<strong>Percutaneous transluminal renal angioplasty (PTRA)</strong>"]
      ]) + Mn("Old man, young woman", "Atherosclerosis in the older man with vascular risk factors; fibromuscular dysplasia (string of beads) in the younger woman.")),
      S("presentation", "When to Suspect RAS", "<ul><li><strong>AKI after starting an ACEI or ARB</strong> — always check a chemistry panel within a week of starting</li><li><strong>Refractory HTN</strong> in a patient with RAS risk factors</li><li><strong>Recurrent flash pulmonary edema</strong></li><li><strong>Abdominal (renal artery) bruit</strong></li></ul><p>History may also show an elevated creatinine or anemia suggesting CKD or RAS.</p>" + HY("Creatinine jumps after an ACEI/ARB → think bilateral (or solitary-kidney) RAS: the kidney depended on angiotensin II to keep filtering.")),
      S("workup", "Diagnostic Studies", Tbl(["Test", "Pros", "Cons / role"], [
        ["<strong>Duplex Doppler renal artery ultrasound</strong>", "Cheap, non-invasive, no radiation", "Operator dependent; <strong>initial test when suspicion is low</strong>"],
        ["<strong>CT or MR angiography</strong>", "Non-invasive, detailed", "More expensive; contrast load, radiation with CT"],
        ["<strong>Renal/aortic angiogram</strong>", "<strong>Gold standard</strong>; can <strong>intervene at the same time</strong>", "Invasive, contrast load"]
      ])),
      S("treatment", "Management", "<p>The lecture shows revascularization: <strong>PTRA (angioplasty) for fibromuscular dysplasia</strong> and <strong>stenting for atherosclerotic RAS</strong>, which can be done during the diagnostic angiogram. Monitor renal function closely if a RAAS blocker is used — stop an ACEI if creatinine rises &gt;30% or hyperkalemia persists.</p>")
    ], [
      Q("pathophysiology", "Why does blood pressure remain high in renal artery stenosis even after volume expands?", ["The stenosis is a fixed obstruction, so the affected kidney keeps sensing low flow and RAAS stays activated", "Aldosterone levels fall as BP rises", "The contralateral kidney stops making renin", "Angiotensin II causes vasodilation"], 0, "Volume expansion and higher BP don’t restore flow past a fixed stenosis, so renin release continues."),
      Q("pathophysiology", "Which organ, besides the heart, is damaged by the persistent high BP of unilateral renal artery stenosis?", ["The normal contralateral kidney", "The adrenal medulla", "The thyroid", "The pancreas"], 0, "Constant high BP stresses the normal kidney with very high vascular pressures and remodels the heart and vessels."),
      Q("populations", "A 34-year-old woman with no vascular risk factors has new, hard-to-control HTN and an abdominal bruit. Angiography shows a “string of beads.” What is the diagnosis?", ["Fibromuscular dysplasia", "Atherosclerotic renal artery stenosis", "Coarctation of the aorta", "Polycystic kidney disease"], 0, "FMD causes RAS in women under 50 and has a classic string-of-beads (pearls) appearance."),
      Q("populations", "Which patient is most typical of atherosclerotic renal artery stenosis?", ["A 66-year-old male smoker with diabetes and PAD", "A 25-year-old woman with palpitations", "A 15-year-old with arm-leg BP difference", "A 40-year-old with heavy snoring"], 0, "Atherosclerotic RAS occurs in men over 50 with CAD risk factors: HLD, tobacco, DM, CKD, PAD."),
      Q("presentation", "A 70-year-old started on lisinopril 6 days ago now has a creatinine that rose from 1.1 to 2.0. Which condition should be suspected?", ["Renal artery stenosis", "Primary hyperaldosteronism", "Pheochromocytoma", "Cushing’s syndrome"], 0, "AKI after starting an ACEI/ARB is a classic clue to RAS — always check a chemistry panel within a week of starting."),
      Q("presentation", "Which is a clinical clue to renovascular hypertension?", ["Recurrent flash pulmonary edema", "Rib notching on chest x-ray", "Paroxysmal diaphoresis and pallor", "Generalized weakness with hypokalemia"], 0, "RAS clues: AKI with ACEI/ARB, refractory HTN with risk factors, recurrent flash pulmonary edema, and an abdominal bruit."),
      Q("workup", "Which is the gold-standard test for renal artery stenosis?", ["Renal angiogram", "Duplex Doppler ultrasound", "CT angiography", "Plasma renin activity"], 0, "Angiography of the aorta and renal arteries is the gold standard and allows intervention at the same time; it is invasive with a dye load."),
      Q("workup", "Suspicion for RAS is low. Which test is generally used first?", ["Duplex Doppler renal artery ultrasound", "Renal angiogram", "MR angiography with gadolinium", "Nuclear renal scan"], 0, "Duplex ultrasound is cheap, non-invasive, and radiation-free — the initial test when suspicion is low, though it depends on operator skill."),
      Q("workup", "What is a disadvantage of CT angiography for evaluating renal artery stenosis?", ["Contrast load and radiation exposure", "It is invasive", "It cannot visualize the renal arteries", "It is the cheapest test but least accurate"], 0, "CT/MR angiography is non-invasive but more expensive; CT adds a dye load and radiation."),
      Q("treatment", "Which intervention is shown for renal artery stenosis caused by fibromuscular dysplasia?", ["Percutaneous transluminal renal angioplasty (PTRA)", "Nephrectomy", "Adrenalectomy", "CPAP"], 0, "The lecture shows FMD before and after PTRA, and atherosclerotic RAS before and after stenting.")
    ]),

    // ------------------------------------------------------------------
    D("htn-coarctation", "Coarctation of the Aorta", "A congenital narrowing of the aorta after the great vessels to the head and arms: high BP and strong pulses in the arms, weak delayed pulses and lower BP in the legs, a chest bruit, and rib notching on CXR.", [
      S("overview", "Overview", "<p>An uncommon, <strong>congenital</strong> cause of secondary HTN, usually discovered in childhood: the aorta narrows <strong>after the take-off of the great vessels</strong> to the head and upper extremities.</p>"),
      S("presentation", "Signs", "<ul><li><strong>Upper-extremity BP and pulses higher than lower-extremity</strong></li><li><strong>Femoral pulse delayed</strong> compared with the radial pulse</li><li><strong>Audible bruit in the chest</strong></li><li><strong>Rib notching on CXR</strong> — inferior rib notching (<strong>Roesler sign</strong>) from dilated intercostal collaterals that bypass the coarctation to supply the descending aorta</li></ul>" + HY("Unequal arm/leg BP + radial–femoral delay + rib notching = coarctation.")),
      S("workup", "Diagnosis", Tbl(["Patient", "Diagnostic test"], [
        ["Child", "<strong>Echocardiogram</strong>"],
        ["Adult", "<strong>CT angiography</strong>"]
      ]))
    ], [
      Q("presentation", "A 17-year-old has BP 168/94 in the right arm and 112/70 in the leg, with delayed femoral pulses. What is the likely diagnosis?", ["Coarctation of the aorta", "Renal artery stenosis", "Pheochromocytoma", "White coat hypertension"], 0, "Higher upper- than lower-extremity BP with a radial–femoral delay points to coarctation."),
      Q("presentation", "What causes the rib notching seen in coarctation of the aorta?", ["Dilated intercostal collateral arteries bypassing the narrowing", "Erosion from enlarged kidneys", "Bone metastases", "Hyperparathyroid bone resorption"], 0, "Inferior rib notching (Roesler sign) comes from dilated intercostal collaterals that carry blood around the coarctation to the descending aorta."),
      Q("presentation", "Which chest x-ray finding is classic for coarctation of the aorta?", ["Inferior rib notching", "Kerley B lines", "Boot-shaped heart", "Widened mediastinum from lymphadenopathy"], 0, "Rib notching (Roesler sign) is the classic CXR finding."),
      Q("overview", "Where is the aorta narrowed in coarctation?", ["After the take-off of the great vessels to the head and arms", "At the aortic valve", "At the renal arteries", "At the iliac bifurcation"], 0, "The narrowing lies after the great vessels supplying the head and upper extremities, so arm pressures are high and leg pressures low."),
      Q("workup", "Which test diagnoses coarctation of the aorta in an adult?", ["CT angiography", "Echocardiogram alone", "Duplex renal ultrasound", "24-hour urine metanephrines"], 0, "Echocardiography is diagnostic in children; CT angiography is used in adults."),
      Q("workup", "A 6-year-old has upper-extremity hypertension and a systolic chest bruit. Which test confirms coarctation?", ["Echocardiogram", "CT angiography", "Renal angiogram", "Cardiac MRI with stress"], 0, "In children, echo is diagnostic; CTA is reserved for adults.")
    ]),

    // ------------------------------------------------------------------
    D("htn-pheochromocytoma", "Pheochromocytoma", "A rare, usually benign catecholamine-secreting tumor of the adrenal medulla: baseline BP normal or mildly high, punctuated by paroxysms of severe HTN with headache, palpitations, sweating, and pallor.", [
      S("pathophysiology", "Pathophysiology", "<p>A rare, usually benign tumor of the <strong>adrenal medulla</strong> made of cells that synthesize <strong>norepinephrine and epinephrine</strong>, released in an uncontrolled, sudden fashion.</p>"),
      S("presentation", "Presentation", "<p>BP is normal to modestly elevated most of the time, with <strong>paroxysms</strong> of very high BP plus <strong>palpitations, diaphoresis, headache, and pallor</strong>. Sudden surges can cause <strong>flash pulmonary edema, MI, and stroke</strong>.</p>" + Mn("Classic triad + P", "Headache, sweating, palpitations — with episodic (labile) HTN and pallor.")),
      S("workup", "Work-up", "<ol><li><strong>24-hour urine metanephrines and catecholamines</strong></li><li>If elevated → <strong>adrenal CT or MRI with IV contrast</strong></li></ol>" + HY("Biochemistry first (24-h urine metanephrines), imaging second.")),
      S("treatment", "Drug Caution", "<p>Giving a <strong>beta-blocker without first giving an alpha-blocker</strong> in pheochromocytoma (or cocaine-induced HTN) is listed as a drug situation that <strong>causes hypertension</strong>: blocking β2 vasodilation leaves catecholamines acting unopposed on α receptors.</p>" + C("unopposed α-adrenergic vasoconstriction is the mechanism; alpha blockade comes before any beta-blocker.") + HY("Pheo: alpha before beta — never a beta-blocker alone."))
    ], [
      Q("pathophysiology", "Where does a pheochromocytoma arise?", ["Adrenal medulla", "Adrenal cortex zona glomerulosa", "Anterior pituitary", "Juxtaglomerular apparatus"], 0, "Pheochromocytoma is a usually benign tumor of the adrenal medulla made of catecholamine-synthesizing cells."),
      Q("presentation", "A 38-year-old has episodes of pounding headache, sweating, palpitations, and pallor; BP during an episode is 220/120 and is normal between episodes. What is the likely diagnosis?", ["Pheochromocytoma", "Primary hyperaldosteronism", "Renal artery stenosis", "Hyperthyroidism"], 0, "Paroxysms of severe HTN with headache, diaphoresis, palpitations, and pallor are the hallmark of catecholamine release from a pheochromocytoma."),
      Q("presentation", "Which complication can follow a sudden catecholamine surge from a pheochromocytoma?", ["Flash pulmonary edema, MI, or stroke", "Hypokalemic paralysis", "Rib notching", "Renal agenesis"], 0, "Severe, sudden BP elevations can cause flash pulmonary edema, MI, and stroke."),
      Q("workup", "What is the initial test for suspected pheochromocytoma?", ["24-hour urine metanephrines and catecholamines", "Adrenal CT", "Plasma renin activity", "TSH"], 0, "Start with 24-hour urine metanephrines and catecholamines; if elevated, image the adrenals with CT or MRI with contrast."),
      Q("workup", "A patient’s 24-hour urine metanephrines are markedly elevated. What is the next step?", ["Adrenal CT or MRI with IV contrast", "Repeat the urine test in 1 year", "Start a beta-blocker and discharge", "Renal angiogram"], 0, "Elevated metanephrines are followed by adrenal imaging (CT or MRI with contrast)."),
      Q("treatment", "Why is a beta-blocker alone dangerous in a patient with pheochromocytoma?", ["It leaves catecholamines unopposed at alpha receptors, worsening hypertension", "It causes hypokalemia", "It causes angioedema", "It increases catecholamine synthesis"], 0, "A beta-blocker without prior alpha blockade is listed as a drug cause of HTN in pheo and cocaine-induced HTN."),
      Q("presentation", "Which history finding points most toward pheochromocytoma rather than primary hyperaldosteronism?", ["Episodic sweating, headache, and labile hypertension", "Generalized weakness with hypokalemia", "Heavy snoring and daytime sleepiness", "Cold intolerance and bradycardia"], 0, "Episodes of sweating, labile HTN, headache, and palpitations suggest pheo; weakness with hypokalemia suggests hyperaldosteronism.")
    ]),

    // ------------------------------------------------------------------
    D("htn-primary-aldosteronism", "Primary Hyperaldosteronism", "Autonomous aldosterone excess from adrenal hyperplasia or an adenoma: hypertension with persistent hypokalemia and metabolic alkalosis, so patients mainly complain of generalized weakness.", [
      S("pathophysiology", "Pathophysiology", "<p>Overproduction of aldosterone by <strong>adrenal hyperplasia</strong> or an <strong>autonomous adrenal adenoma</strong>. Aldosterone drives <strong>Na and water retention</strong> (HTN) while <strong>K+ and H+ are wasted in the urine</strong> → <strong>persistent hypokalemia</strong> and <strong>metabolic alkalosis</strong>.</p>"),
      S("presentation", "Presentation", "<p>Hypertension plus <strong>generalized weakness</strong> from persistent hypokalemia. On history, “generalized weakness coupled with hypokalemia suggests hyperaldosteronism.” Persistent hypokalemia is a listed trigger to screen for secondary HTN.</p><p><strong>Mimic:</strong> black licorice (or licorice root in supplements) lowers K+ and raises BP.</p>" + HY("Hypertension + unexplained hypokalemia + metabolic alkalosis + weakness = think primary hyperaldosteronism.")),
      S("workup", "Work-up", "<p>The slides do not name a specific test; baseline electrolytes in every new-HTN work-up reveal the hypokalemia.</p>" + C("screen with a plasma aldosterone-to-renin ratio: aldosterone high with renin suppressed (low) in primary hyperaldosteronism, versus aldosterone high with renin high in renal artery stenosis (secondary hyperaldosteronism)."))
    ], [
      Q("pathophysiology", "What causes primary hyperaldosteronism?", ["Adrenal hyperplasia or an autonomous adrenal adenoma", "Renal artery stenosis", "An ACTH-secreting pituitary adenoma", "A tumor of the adrenal medulla"], 0, "Primary hyperaldosteronism is aldosterone overproduction by adrenal hyperplasia or an autonomous adrenal adenoma."),
      Q("pathophysiology", "Which acid–base and potassium pattern fits primary hyperaldosteronism?", ["Hypokalemia with metabolic alkalosis", "Hyperkalemia with metabolic acidosis", "Normal potassium with respiratory alkalosis", "Hyperkalemia with metabolic alkalosis"], 0, "Constant sodium reabsorption wastes K+ and H+ in the urine, causing hypokalemia and metabolic alkalosis."),
      Q("presentation", "A 44-year-old with resistant hypertension complains of generalized weakness. K+ is 2.9 and bicarbonate 31; she takes no diuretics. What is the most likely cause?", ["Primary hyperaldosteronism", "Pheochromocytoma", "Coarctation of the aorta", "Hypothyroidism"], 0, "HTN with persistent hypokalemia, metabolic alkalosis, and generalized weakness suggests primary hyperaldosteronism."),
      Q("presentation", "What is the chief complaint most patients with primary hyperaldosteronism have?", ["Generalized weakness", "Episodic palpitations and sweating", "Flank pain and hematuria", "Heavy snoring"], 0, "Patients primarily complain of generalized weakness from persistent hypokalemia."),
      Q("presentation", "Which dietary substance can mimic primary hyperaldosteronism by lowering potassium and raising BP?", ["Black licorice", "Grapefruit juice", "Green tea", "Dark chocolate"], 0, "Black licorice or licorice root in herbal supplements lowers K+ and raises BP."),
      Q("workup", "Which renin and aldosterone pattern distinguishes primary hyperaldosteronism from renal artery stenosis?", ["High aldosterone with low renin", "High aldosterone with high renin", "Low aldosterone with high renin", "Low aldosterone with low renin"], 0, "Clarification (standard reference): primary hyperaldosteronism is autonomous, so renin is suppressed; RAS raises both renin and aldosterone.")
    ]),

    // ------------------------------------------------------------------
    D("htn-osa", "Obstructive Sleep Apnea–Related Hypertension", "OSA is present in over half of people with hypertension. Suspect it with resistant HTN, heavy snoring, obesity, and daytime sleepiness; nighttime hypoxia drives sympathetic activity.", [
      S("pathophysiology", "Pathophysiology and Epidemiology", "<p>OSA occurs in <strong>&gt;50% of individuals with HTN</strong>. Repeated <strong>hypoxia triggers sympathetic nervous system activity</strong>, raising BP. Insufficient sleep (&lt;7 h nightly) is itself associated with HTN.</p>"),
      S("presentation", "When to Suspect", "<ul><li><strong>Resistant HTN</strong></li><li><strong>Heavy snoring</strong>, daytime sleepiness</li><li><strong>Obesity</strong></li></ul><p>A prior OSA diagnosis is one of the important past events to ask about in every new hypertensive patient.</p>"),
      S("treatment", "Treatment", "<p><strong>CPAP</strong> effectively treats OSA. It <strong>may not relieve the HTN by itself</strong>, but it makes antihypertensive medications <strong>more effective</strong>.</p>" + HY("CPAP treats the apnea and makes BP drugs work better — it does not reliably cure the hypertension alone."))
    ], [
      Q("pathophysiology", "Roughly what proportion of people with hypertension have obstructive sleep apnea?", ["More than 50%", "About 5%", "About 20%", "Less than 1%"], 0, "OSA occurs in more than half of individuals with HTN."),
      Q("pathophysiology", "How does obstructive sleep apnea raise blood pressure?", ["Hypoxia triggers sympathetic nervous system activity", "It causes autonomous aldosterone secretion", "It narrows the renal arteries", "It releases catecholamines from the adrenal medulla"], 0, "Recurrent hypoxia activates the sympathetic nervous system, raising BP."),
      Q("presentation", "A 52-year-old obese man remains at 150/94 on three drugs including a thiazide. His wife reports loud snoring, and he falls asleep at red lights. What secondary cause is most likely?", ["Obstructive sleep apnea", "Coarctation of the aorta", "Pheochromocytoma", "Fibromuscular dysplasia"], 0, "Resistant HTN with snoring, obesity, and daytime sleepiness should prompt evaluation for OSA."),
      Q("treatment", "What is the effective treatment for OSA in a hypertensive patient?", ["CPAP", "A fourth antihypertensive alone", "An alpha-1 blocker at bedtime", "Adrenalectomy"], 0, "CPAP is the effective treatment for OSA."),
      Q("treatment", "What effect does CPAP have on hypertension in OSA?", ["It may not relieve HTN by itself but makes antihypertensives more effective", "It reliably cures the hypertension", "It worsens BP control", "It replaces the need for any antihypertensive"], 0, "CPAP may not resolve the HTN but makes medication more responsive."),
      Q("presentation", "Which three features in a hypertensive patient should prompt consideration of OSA?", ["Resistant HTN, snoring, obesity", "Hypokalemia, weakness, alkalosis", "Episodic sweating, headache, palpitations", "Arm-leg BP difference, bruit, rib notching"], 0, "Consider OSA with resistant HTN, snoring, and obesity. The other sets describe hyperaldosteronism, pheochromocytoma, and coarctation.")
    ]),

    // ------------------------------------------------------------------
    D("htn-drug-induced", "Drug- and Substance-Induced Hypertension", "Hypertension caused or worsened by a medication, supplement, food, or street drug — NSAIDs, decongestants, OCPs, triptans, alcohol, cocaine, meth, licorice, St. John’s wort — or by stopping a beta-blocker or clonidine abruptly. Always take an OTC and substance history.", [
      S("prescription", "Prescription and OTC Medications", Tbl(["Drug", "Teaching point"], [
        ["<strong>NSAIDs, COX-2 inhibitors</strong>", "Raise BP ~5 mmHg on average; avoid in borderline or elevated BP"],
        ["<strong>Pseudoephedrine / ephedra</strong>", "Sympathomimetic decongestants"],
        ["<strong>Estrogens / high-dose OCPs</strong>", "Ask about oral contraceptives in every new hypertensive"],
        ["<strong>Migraine meds (triptans)</strong>", "Listed cause"],
        ["Psych meds", "SNRIs, tricyclic antidepressants"],
        ["Others", "Carbamazepine, metoclopramide"]
      ]) + C("NSAIDs block renal prostaglandins and cause sodium/water retention; estrogen raises hepatic angiotensinogen; triptans are 5-HT1B/1D agonists that vasoconstrict.")),
      S("substances", "Alcohol, Street Drugs, and Natural Products", Tbl(["Substance", "Teaching point"], [
        ["<strong>Alcohol</strong>", "Chronic use is a <strong>common, hard-to-treat cause</strong>; &gt;2 drinks/day (40 g) or binges; ↑ plasma catecholamines"],
        ["<strong>Cocaine, methamphetamine</strong>", "Illicit sympathomimetics; cocaine <em>withdrawal</em> also raises BP"],
        ["<strong>St. John’s wort</strong>", "Herbal product on the list"],
        ["<strong>Black licorice</strong>", "Lowers K+ and raises BP"],
        ["Sodium", "Dietary cause"],
        ["Others", "Ephedra (ma-huang), “herbal ecstasy,” phenylpropanolamine analogs, nicotine and narcotic withdrawal, anabolic steroids, methylphenidate, phencyclidine, ketamine, ergot-containing herbals"]
      ]) + C("St. John’s wort has MAO-inhibitor–like activity and induces CYP450 enzymes, which can lower levels of co-prescribed drugs, including some antihypertensives.")),
      S("withdrawal", "Dangerous Drug Situations", "<ul><li><strong>Abrupt discontinuation of a beta-blocker</strong> → rebound HTN, worsening angina, or MI (taper over 1–2 weeks)</li><li><strong>Abrupt discontinuation of clonidine</strong> (central α2-agonist) → <strong>rebound HTN</strong>, a significant risk</li><li><strong>Beta-blocker without an alpha-blocker first</strong> in cocaine-induced HTN or pheochromocytoma</li></ul>" + HY("Never stop clonidine or a beta-blocker abruptly; never give a beta-blocker alone for cocaine-induced HTN.")),
      S("management", "Approach", "<p>Take a medication, OTC, supplement, and substance history at diagnosis and when BP becomes resistant. Remove or reduce the offender when possible (stop NSAIDs, decongestants, licorice; counsel on alcohol moderation — ≤1 drink/day for women and smaller men, ≤2 for larger men). Interfering substances are part of the resistant-HTN checklist.</p>")
    ], [
      Q("prescription", "About how much do NSAIDs raise blood pressure on average?", ["About 5 mmHg", "About 20 mmHg", "About 1 mmHg", "About 40 mmHg"], 0, "NSAIDs raise BP about 5 mmHg on average and are best avoided in borderline or elevated BP."),
      Q("prescription", "A previously controlled hypertensive patient’s BP rises to 152/94 after a week of a cold. Which OTC product is most likely responsible?", ["Pseudoephedrine", "Acetaminophen", "Guaifenesin", "Saline nasal spray"], 0, "Pseudoephedrine (and ephedra) are sympathomimetics listed as drug causes of HTN."),
      Q("prescription", "A 26-year-old woman develops new hypertension. Which medication history is most important to ask about?", ["Oral contraceptives", "Inhaled corticosteroids", "Proton pump inhibitors", "Topical antifungals"], 0, "Estrogens and high-dose oral contraceptives are listed causes; ask about OCPs, OTC meds, alcohol, and illicit drugs in every new hypertensive."),
      Q("prescription", "Which migraine medication class does the lecture list as raising blood pressure?", ["Triptans", "Acetaminophen", "Magnesium", "Riboflavin"], 0, "Migraine medications (triptans) are on the prescription drug list; they cause vasoconstriction."),
      Q("substances", "Which substance is described as a common cause of hypertension that can be very difficult to treat?", ["Chronic alcohol use", "Caffeine", "Marijuana", "Green tea"], 0, "Chronic alcohol use is a common, hard-to-treat cause; HTN is difficult to control above 40 g (2 drinks) daily or with binges."),
      Q("substances", "Which herbal product is on the lecture’s list of causes of drug-induced hypertension?", ["St. John’s wort", "Chamomile", "Peppermint", "Echinacea"], 0, "St. John’s wort is listed among natural products that raise BP, along with ephedra and ergot-containing herbals."),
      Q("substances", "Which pair of illicit drugs are sympathomimetics that raise blood pressure?", ["Cocaine and methamphetamine", "Heroin and fentanyl", "Marijuana and psilocybin", "Benzodiazepines and barbiturates"], 0, "Cocaine and methamphetamine are illicit sympathomimetics; cocaine withdrawal is also listed."),
      Q("withdrawal", "A patient stops his clonidine abruptly because he ran out. What is the main risk?", ["Rebound hypertension", "Hypotension", "Hyperkalemia", "Angioedema"], 0, "Abrupt discontinuation of clonidine causes rebound hypertension — a significant risk."),
      Q("withdrawal", "Why should metoprolol not be stopped abruptly?", ["Rebound hypertension, worsening angina, or MI", "It causes hypokalemia", "It causes angioedema", "It causes drug-induced lupus"], 0, "Abrupt beta-blocker withdrawal can cause rebound HTN, worsening angina, or MI; taper over 1–2 weeks."),
      Q("withdrawal", "A man with cocaine-induced hypertension is given a beta-blocker alone. What is the concern?", ["Unopposed alpha stimulation worsens hypertension", "Hypoglycemia", "Hyperkalemia", "Bronchodilation"], 0, "A beta-blocker without an alpha-blocker first in cocaine-induced HTN or pheochromocytoma is listed as a cause of HTN.")
    ]),

    // ------------------------------------------------------------------
    D("htn-resistant", "Resistant Hypertension", "BP above goal despite maximum tolerated doses of three drugs, one of them a thiazide. Confirm adherence and home readings, remove interfering substances, add a fourth drug (often spironolactone), and look for secondary causes.", [
      S("definition", "Definition", "<p><strong>Resistant HTN:</strong> BP not controlled to goal on the <strong>maximum tolerated doses of three antihypertensives, one of which is a thiazide diuretic</strong>.</p><p>The most widely used three-drug regimen — <strong>ACEI (or ARB) + CCB + thiazide</strong> — controls BP in about <strong>80%</strong> of patients. Secondary causes account for ~20% of resistant HTN.</p>" + HY("Resistant = uncontrolled on 3 maxed drugs including a thiazide.")),
      S("evaluation", "Evaluation", "<ol><li><strong>Ensure medication adherence</strong></li><li><strong>Monitor BP at home</strong> (exclude white coat effect and technique error)</li><li><strong>Exclude interfering meds/substances</strong> — NSAIDs, decongestants, OCPs, alcohol, stimulants, licorice</li><li><strong>Work up secondary causes</strong> — OSA, primary hyperaldosteronism, RAS, pheochromocytoma, CKD</li><li>Consider <strong>referral to a hypertension specialist</strong></li></ol>"),
      S("fourth-drug", "Adding a Fourth Drug", "<p>Options: an <strong>aldosterone antagonist</strong>, <strong>beta-blocker</strong>, <strong>centrally acting agent</strong>, <strong>alpha-blocker</strong>, or <strong>direct vasodilator</strong>.</p>" + Tbl(["Class", "Mechanism", "Adverse effects / cautions", "Other uses"], [
        ["<strong>Aldosterone antagonists</strong>: spironolactone, eplerenone", "Competitively block the mineralocorticoid receptor in the distal tubule → fewer Na-K pumps, Na lost, K retained", "<strong>Hyperkalemia</strong> (with ACEI/ARB/K supplements; GFR &lt;50, DM, proteinuria) — monitor chemistry. <strong>Spironolactone</strong> also binds androgen/progesterone receptors → <strong>gynecomastia, irregular menses, impotence</strong>; <strong>eplerenone</strong> is more selective", "Compelling indication in <strong>HFrEF</strong>; initial diuretic for <strong>ascites</strong> in chronic liver disease"],
        ["<strong>α1-blockers</strong>: terazosin, doxazosin, prazosin", "Block α1 on arteries and veins → vasodilation; relax prostate", "<strong>Orthostatic hypotension</strong> (older adults); <strong>first-dose phenomenon</strong> (dizziness, syncope 1–3 h after first dose); edema. <strong>Dose at bedtime</strong>. Not appropriate monotherapy", "<strong>BPH</strong>"],
        ["<strong>Central α2-agonists</strong>: clonidine (PO or weekly patch), methyldopa, guanfacine", "Stimulate brain α2 receptors → ↓ sympathetic outflow, ↑ vagal tone", "<strong>Rebound HTN</strong> if stopped abruptly (clonidine); orthostasis, bradycardia, sedation, dizziness, HA, fatigue; dry mouth, constipation; Na/water retention. Clonidine is PO bid–tid (adherence)", "Clonidine: <strong>alcohol withdrawal</strong>; safe and strong in <strong>ESRD</strong>. Methyldopa: <strong>pregnancy</strong>"],
        ["<strong>Direct arterial vasodilators</strong>: hydralazine, minoxidil", "Relax arterial smooth muscle; little venous effect", "<strong>Na/water retention</strong> (pair with a loop), <strong>reflex tachycardia</strong>, <strong>angina/vascular steal</strong> in CAD; hydralazine → <strong>drug-induced lupus</strong>; minoxidil → <strong>hair growth</strong>", "Hydralazine: IV or PO, HR neutral, HF combinations, safe in CKD/AKI/ESRD. Minoxidil: difficult HTN in renal failure"]
      ]) + HY("Spironolactone is the classic 4th drug — watch potassium, especially with an ACEI/ARB.")),
      S("clonidine-overdose", "Clonidine Overdose", "<p>Symptoms within about <strong>1 hour</strong> of tablets (later with a patch). It <strong>looks like an opioid overdose</strong>: <strong>pinpoint pupils</strong>, depressed consciousness, hypotension, bradycardia, coma, <strong>respiratory depression</strong>, and <strong>hypothermia</strong>.</p><p>Treat with <strong>naloxone</strong>, IV fluids, atropine, pacing, and vasopressors.</p>" + HY("Pinpoint pupils + respiratory depression + hypotension in someone with a clonidine prescription — treat like an opioid overdose (naloxone)."))
    ], [
      Q("definition", "Which best defines resistant hypertension?", ["BP above goal despite maximum tolerated doses of three antihypertensives, including a thiazide", "BP above goal on any two drugs", "Stage 2 hypertension at diagnosis", "BP ≥180/120 without end-organ damage"], 0, "Resistant HTN is uncontrolled BP on maximum tolerated doses of three drugs, one of which is a thiazide diuretic."),
      Q("definition", "Which three-drug regimen controls BP in about 80% of patients?", ["ACEI or ARB + CCB + thiazide", "Beta-blocker + loop + clonidine", "ACEI + ARB + thiazide", "Alpha-blocker + hydralazine + spironolactone"], 0, "ACEI (or ARB) + CCB + thiazide is the most widely used three-drug combination. ACEI + ARB is never combined."),
      Q("evaluation", "A patient’s BP remains 148/92 on lisinopril, amlodipine, and chlorthalidone at maximum doses. What is the first step?", ["Confirm adherence and home BP readings and look for interfering substances", "Add an ARB", "Order a renal angiogram immediately", "Stop all medications"], 0, "Ensure adherence, monitor BP at home, and exclude interfering meds or intake before adding a fourth drug or working up secondary causes."),
      Q("fourth-drug", "Which class is NOT listed as a fourth-drug option for resistant hypertension?", ["A second ACE inhibitor", "Aldosterone antagonist", "Alpha-blocker", "Direct vasodilator"], 0, "Fourth-drug options: aldosterone antagonist, beta-blocker, centrally acting agent, alpha-blocker, or direct vasodilator."),
      Q("fourth-drug", "A man with resistant HTN started on spironolactone develops breast enlargement. Which change keeps the same mechanism with fewer endocrine effects?", ["Switch to eplerenone", "Switch to amiloride", "Switch to furosemide", "Add an ARB"], 0, "Spironolactone also binds androgen and progesterone receptors (gynecomastia, impotence, irregular menses); eplerenone is more selective for the mineralocorticoid receptor."),
      Q("fourth-drug", "A patient on lisinopril is started on spironolactone. What must be monitored?", ["Serum potassium (hyperkalemia)", "Serum calcium (hypercalcemia)", "Uric acid (gout)", "Hearing (ototoxicity)"], 0, "Aldosterone antagonists cause hyperkalemia, especially with an ACEI, ARB, or K supplements and in GFR <50, DM, or proteinuria."),
      Q("fourth-drug", "A 68-year-old man with HTN and BPH starts doxazosin and faints an hour after the first dose. What explains this?", ["First-dose phenomenon of an alpha-1 blocker", "Clonidine rebound", "Drug-induced lupus", "Beta-blocker heart block"], 0, "Alpha-1 blockers cause transient dizziness, palpitations, or syncope 1–3 hours after the first dose; dose them at bedtime."),
      Q("fourth-drug", "When are alpha-1 blockers typically chosen for hypertension?", ["When comorbid BPH also needs treatment", "As first-line monotherapy", "In pregnancy", "Post-MI"], 0, "Alpha-1 blockers are not appropriate monotherapy but are often used when both HTN and BPH need treatment."),
      Q("fourth-drug", "A patient on hydralazine develops arthralgias, rash, and a positive ANA. What is the likely cause?", ["Drug-induced lupus from hydralazine", "Minoxidil hypertrichosis", "ACE inhibitor angioedema", "Thiazide-induced gout"], 0, "Hydralazine is known to cause drug-induced lupus."),
      Q("fourth-drug", "Which adverse effect is characteristic of minoxidil?", ["Excessive hair growth", "Dry cough", "Gynecomastia", "Ototoxicity"], 0, "Minoxidil causes hypertrichosis; both direct vasodilators cause fluid retention and reflex tachycardia."),
      Q("fourth-drug", "Why are direct arterial vasodilators often given with a loop diuretic?", ["They cause sodium and water retention", "They cause hyperkalemia", "They cause bradycardia", "They lower the GFR"], 0, "Hydralazine and minoxidil cause Na/water retention and edema, minimized by adding a loop diuretic."),
      Q("fourth-drug", "Why are direct arterial vasodilators used cautiously in coronary artery disease?", ["Reflex tachycardia and vascular steal can provoke angina", "They cause coronary vasospasm", "They raise LDL", "They cause heart block"], 0, "Excessive vasodilation causes reflex tachycardia and possible vascular steal, provoking angina."),
      Q("fourth-drug", "Which non-BP indication does clonidine have?", ["Alcohol withdrawal", "Migraine prophylaxis", "BPH", "Atrial fibrillation rate control"], 0, "Clonidine counteracts sympathetically mediated alcohol-withdrawal symptoms; it is also safe and strong in ESRD."),
      Q("clonidine-overdose", "A toddler who chewed a grandparent’s clonidine patch is lethargic, with pinpoint pupils, slow breathing, hypotension, and a low temperature. What is the first antidote to give?", ["Naloxone", "Glucagon", "Flumazenil", "Lipid emulsion"], 0, "Clonidine overdose mimics an opioid overdose (miosis, depressed LOC, respiratory depression, hypotension, hypothermia); treat with naloxone, fluids, atropine, pacing, and pressors."),
      Q("clonidine-overdose", "Which finding helps distinguish clonidine overdose from a beta-blocker overdose?", ["Pinpoint pupils with hypothermia", "Bradycardia", "Hypotension", "Hypoglycemia"], 0, "Both cause bradycardia and hypotension; clonidine causes opioid-like miosis, respiratory depression, and hypothermia. Hypoglycemia fits beta-blocker overdose.")
    ]),

    // ------------------------------------------------------------------
    D("htn-compelling-indications", "Hypertension With Compelling Indications", "Hypertension plus a condition — HFrEF, post-MI, CAD, AF, diabetes, CKD/proteinuria, or prior stroke — where a specific drug class has proven survival benefit. Compelling indications override race- and age-based first-line choices; this is where beta-blockers and non-DHP CCBs earn their place.", [
      S("concept", "Concept and Regimens", "<p><strong>Compelling indications</strong> are high-risk conditions that are direct sequelae of HTN or commonly associated with it; a specific class is started because it has <strong>evidence-based survival benefit</strong>. Listed: HF, post-MI, CAD, PAD, AF, stroke, DM, CKD.</p>" + compellingTable + HY("Compelling indications trump everything — a Black patient with HFrEF or prior MI still gets a beta-blocker and an ACEI/ARB.")),
      S("raas-blockers", "ACE Inhibitors and ARBs in DM, CKD, HF, and Post-MI", "<p>ACEIs (or ARBs) are the <strong>treatment of choice in CKD with proteinuria</strong> to slow progression, reduce morbidity and mortality in <strong>HFrEF and after MI</strong>, and may halt or regress LV remodeling in HF, CAD, and cardiomyopathy. They are first for DM, CKD, and recurrent stroke prevention, followed by a DHP-CCB or thiazide.</p><p>Monitor K and creatinine within about a week; a nephrologist may start an ACEI in more advanced CKD than a primary care provider would.</p>"),
      S("beta-blockers", "Beta-Blockers", "<p>β1 receptors (heart, kidney): ↑ HR, contractility, renin. β2 (lungs, liver, pancreas, arterioles): bronchodilation, vasodilation, insulin secretion, glycogenolysis.</p><p><strong>Not first line for HTN</strong> (no proven reduction of stroke or mortality from HTN) <strong>except with a compelling cardiac indication</strong>: post-MI (STEMI or NSTEMI), compensated HFrEF or any LV dysfunction (EF &lt;50%), CAD, AF. Less effective in Black patients; use with caution over age 60 without an indication.</p>" + Tbl(["Type", "Drugs", "Key points"], [
        ["<strong>Cardioselective (β1)</strong>", "Bisoprolol, metoprolol succinate (daily), metoprolol tartrate (bid), atenolol", "Tachyarrhythmias (AF, sinus tachycardia); <strong>selectivity lost at high doses</strong>"],
        ["<strong>Non-selective (β1 + β2)</strong>", "Propranolol, nadolol, timolol", "Rarely for HTN; used for <strong>migraine prophylaxis, anxiety, essential tremor, portal HTN, thyrotoxicosis</strong>"],
        ["<strong>ISA</strong> (partial agonist)", "Acebutolol", "Don’t lower resting HR/CO; niche (bradycardia); <strong>contraindicated post-MI</strong> or high risk; less cardioprotective"],
        ["<strong>Mixed α1/β</strong>", "<strong>Carvedilol</strong>, labetalol", "Carvedilol: <strong>mortality benefit in HFrEF</strong>, less effect on glucose; more <strong>orthostatic hypotension</strong> than a pure BB. Labetalol: oral or IV prn; <strong>safe in pregnancy</strong>"]
      ]) + "<ul><li><strong>Caution in asthma/COPD</strong> regardless of selectivity</li><li>Side effects: <strong>bradycardia/heart block</strong> (stop the drug), fatigue, reduced exercise tolerance, impotence</li><li><strong>Diabetes:</strong> mask hypoglycemia warning signs (tremor, sweating, tachycardia) and reduce insulin release → not for HTN in DM unless compelling indication</li><li>Start low and titrate slowly in LV dysfunction/HFrEF; <strong>never stop abruptly</strong> (taper 1–2 weeks)</li></ul>" + Tbl(["Beta-blocker overdose", ""], [
        ["Findings", "Hypotension, <strong>bradyarrhythmia</strong>, confusion, <strong>hyperkalemia, hypoglycemia</strong>, myocardial depression/cardiogenic shock. <strong>Propranolol and carvedilol</strong> (most lipophilic) cross the BBB → <strong>seizures, delirium</strong>"],
        ["Treatment", "IV fluids and atropine first; then IV calcium, <strong>IV glucagon</strong> (contractility), vasopressors, <strong>high-dose insulin + glucose</strong>, <strong>lipid emulsion</strong>"]
      ])),
      S("non-dhp-ccb", "Non-Dihydropyridine CCBs (Verapamil, Diltiazem)", "<p>Act mainly on cardiac Ca channels: <strong>negative inotropy and chronotropy</strong> (slow SA/AV nodes). Indication: <strong>AF rate control</strong> and other supraventricular tachyarrhythmias. Available PO/IV.</p><ul><li>Adverse: <strong>bradycardia, AV block</strong>, worsening systolic HF; <strong>constipation (verapamil, ~25%)</strong>; less edema than DHPs</li><li>Avoid in <strong>sick sinus syndrome, 2nd/3rd-degree AV block</strong>, and <strong>acutely decompensated HFrEF</strong> (may resume after ~24 h of diuresis)</li><li><strong>Caution when combined with a beta-blocker</strong></li><li>HFrEF regimen: <strong>avoid non-DHP CCB</strong></li></ul>" + C("the slide says “just like the DHP CCBs, beta-blockers may precipitate heart block”; it is the non-DHP CCBs that share this effect."))
    ], [
      Q("concept", "What makes a condition a “compelling indication” for a specific antihypertensive class?", ["The class has evidence-based survival benefit in that condition", "The class is the cheapest option", "The class has the fewest side effects", "The class works fastest"], 0, "Compelling indications are high-risk conditions linked to HTN in which a particular class has evidence-based survival benefit."),
      Q("concept", "A hypertensive patient has HFrEF with EF 30%. Which regimen does the lecture recommend?", ["ACEI or ARB + beta-blocker + aldosterone antagonist + diuretic", "DHP CCB + thiazide", "Verapamil + ACEI", "Clonidine + hydralazine"], 0, "HFrEF: ACEI/ARB + beta-blocker + aldosterone antagonist + diuretic, getting at least the first 2–3 on board; avoid non-DHP CCBs."),
      Q("concept", "A hypertensive patient is recovering from an NSTEMI. Which two classes should both be started?", ["Beta-blocker and ACEI or ARB", "Thiazide and DHP CCB", "Alpha-blocker and clonidine", "ACEI and ARB"], 0, "Post-MI: beta-blocker plus ACEI or ARB — get both on board."),
      Q("concept", "A 60-year-old with hypertension and atrial fibrillation needs rate control. Which classes are preferred first?", ["Beta-blocker or non-DHP CCB", "DHP CCB or thiazide", "Alpha-1 blocker or clonidine", "Loop diuretic or hydralazine"], 0, "AF: beta-blocker or non-DHP CCB, then ACEI or ARB, then a thiazide."),
      Q("concept", "A 55-year-old with type 2 diabetes and hypertension has no other conditions. What is the preferred first class?", ["ACEI or ARB", "Beta-blocker", "Thiazide", "Alpha-1 blocker"], 0, "Diabetes: ACEI or ARB first, then a DHP-CCB or thiazide. Thiazides and beta-blockers worsen glucose control."),
      Q("raas-blockers", "Which drug class is the treatment of choice to slow progression of CKD with proteinuria?", ["ACE inhibitor", "DHP calcium channel blocker", "Beta-blocker", "Loop diuretic"], 0, "ACEIs (or ARBs) are the treatment of choice in CKD with proteinuria; DHP-CCB or thiazide is added second."),
      Q("raas-blockers", "Which hypertensive patient should get an ACEI or ARB first for secondary prevention?", ["A patient with a prior ischemic stroke", "A patient with BPH", "A patient in alcohol withdrawal", "A patient with essential tremor"], 0, "Recurrent stroke prevention: ACEI or ARB, then a thiazide or DHP-CCB."),
      Q("beta-blockers", "A 50-year-old Black man with hypertension had an MI last year. Which statement about beta-blockers applies?", ["He should receive one — compelling indications trump race-based choices", "Avoid them because they are less effective in Black patients", "Use a thiazide instead", "Use an ISA beta-blocker"], 0, "Beta-blockers are less effective for HTN in Black patients, but compelling indications trump all else — prior MI, HF, or LV dysfunction warrant a beta-blocker."),
      Q("beta-blockers", "Why are beta-blockers avoided for hypertension in diabetics without a compelling indication?", ["They mask hypoglycemia warning signs and decrease insulin release", "They cause hyperglycemia only in type 1 diabetes", "They cause diabetic ketoacidosis", "They raise A1c by increasing glucagon"], 0, "Beta-blockade hides sympathetic warning signs (tremor, sweating, tachycardia) and reduces pancreatic insulin release."),
      Q("beta-blockers", "A hypertensive patient with essential tremor and migraines needs a beta-blocker. Which type fits these non-BP indications?", ["Non-selective (propranolol)", "Cardioselective (metoprolol)", "ISA (acebutolol)", "None — beta-blockers worsen tremor"], 0, "Non-selective beta-blockers are used for migraine prophylaxis, anxiety, essential tremor, portal hypertension, and thyrotoxicosis."),
      Q("beta-blockers", "Which beta-blocker type is contraindicated after a myocardial infarction?", ["Intrinsic sympathomimetic activity (acebutolol)", "Cardioselective (metoprolol)", "Mixed alpha/beta (carvedilol)", "Cardioselective (bisoprolol)"], 0, "ISA beta-blockers are partial agonists, less cardioprotective, and contraindicated post-MI or in high-risk patients."),
      Q("beta-blockers", "Which beta-blocker has proven mortality benefit in HFrEF and causes more orthostatic hypotension than a pure beta-blocker?", ["Carvedilol", "Atenolol", "Propranolol", "Acebutolol"], 0, "Carvedilol (mixed alpha-1/beta) reduces mortality in HFrEF; the added alpha blockade lowers standing BP more and causes more orthostasis."),
      Q("beta-blockers", "A patient took a large propranolol overdose and is bradycardic, hypotensive, hypoglycemic, and seizing. Why are seizures prominent?", ["Propranolol is highly lipophilic and crosses the blood–brain barrier", "Hyperkalemia causes seizures", "Propranolol is a sodium channel opener", "Seizures always occur in any beta-blocker overdose"], 0, "Propranolol and carvedilol are the most lipophilic beta-blockers and cause the most neurotoxicity (seizures, delirium)."),
      Q("beta-blockers", "After IV fluids and atropine, which treatment improves contractility in beta-blocker overdose?", ["IV glucagon", "Naloxone", "Flumazenil", "Physostigmine"], 0, "Beta-blocker overdose: IV fluids and atropine, then IV calcium, IV glucagon, vasopressors, high-dose insulin with glucose, and lipid emulsion."),
      Q("non-dhp-ccb", "A patient with hypertension and acutely decompensated HFrEF is in AF with RVR. Which drug should be avoided?", ["Diltiazem", "Furosemide", "Lisinopril", "Spironolactone"], 0, "Non-DHP CCBs depress contractility and can worsen decompensated HFrEF; they may be resumed after about 24 hours of diuresis once compensated."),
      Q("non-dhp-ccb", "A patient on verapamil complains of a new adverse effect that occurs in about 25% of users. Which is it?", ["Constipation", "Dry cough", "Gynecomastia", "Hair growth"], 0, "Constipation is a common adverse effect of verapamil (~25%)."),
      Q("non-dhp-ccb", "In which condition are non-dihydropyridine CCBs contraindicated?", ["Second- or third-degree AV block", "Atrial fibrillation", "Supraventricular tachycardia", "Stable angina"], 0, "Verapamil and diltiazem slow the SA and AV nodes, so avoid them in sick sinus syndrome and higher-degree AV block; use caution with beta-blockers.")
    ]),

    // ------------------------------------------------------------------
    D("htn-special-populations", "Hypertension in Special Populations", "Drug choice changes with patient characteristics: CCBs and thiazides work best in Black patients; older adults have isolated systolic HTN and need a slow, low start (or tolerance of higher BP after 75); ACEIs/ARBs are forbidden with pregnancy potential; and advanced CKD/ESRD favors CCBs, beta-blockers, hydralazine, and clonidine.", [
      S("black-patients", "Black Patients", "<ul><li>HTN is more common, starts <strong>younger</strong>, is <strong>more severe</strong>, and is more responsive to sodium, obesity, and diet</li><li>Higher risk of stroke (1.3× nonfatal, 1.8× fatal) and <strong>4× renal complications/ESKD</strong></li><li><strong>CCBs and thiazides work best</strong>; ACEIs/ARBs and beta-blockers are less effective (ACEI/ARB second or third line)</li><li><strong>ACEI angioedema is more common</strong> in Black and Asian patients</li><li>Compelling indications still override these choices</li></ul>" + Tbl(["Patient group", "First choice", "Then"], [
        ["Black patients (any age)", "<strong>CCB or thiazide</strong>", "ACEI/ARB second or third line"],
        ["White / non-Black patients &lt;60", "<strong>ACEI or ARB</strong>", "CCB or thiazide"]
      ]) + Mn("Black patients: “C and T”", "Calcium channel blockers and Thiazides first.")),
      S("older-adults", "Older Adults", "<ul><li>Older adults often have <strong>isolated systolic HTN</strong> with a wide pulse pressure (arterial non-compliance); <strong>after 60, systolic BP is the main determinant of CV risk</strong> (in younger adults it is diastolic)</li><li>Age &gt;60: <strong>thiazide, ACEI, or ARB preferred</strong> (Whites ACEI/ARB; Blacks CCB/thiazide); beta-blockers used with caution without a compelling indication</li><li>More drug-sensitive: <strong>start low, titrate slowly, single agent</strong>; target may be less aggressive</li><li>Check <strong>orthostatic BP</strong>; alpha-blockers and carvedilol worsen orthostasis</li><li>Avoid thiazides with balance problems, urinary incontinence, SSRI use, gout, or hyponatremia</li></ul>" + Tbl(["Consider withholding drugs for stage 1 HTN (130–139/80–89) in patients &gt;75 with", ""], [
        ["Recurrent falls", "Dementia"],
        ["Extended care facility residence", "Multiple (non-HTN) comorbidities"],
        ["Orthostatic hypotension", "Limited life expectancy"]
      ])),
      S("pregnancy", "Pregnancy and Pregnancy Potential", Tbl(["Safe / OK", "Avoid"], [
        ["<strong>Labetalol</strong> — lots of experience, safe (oral or IV)", "<strong>ACE inhibitors</strong> — contraindicated (category X): <strong>fetal renal agenesis</strong>"],
        ["<strong>Methyldopa</strong> — one of the safest; rarely used otherwise", "<strong>ARBs</strong> — same renal agenesis risk"],
        ["Thiazides, DHP-CCBs, beta-blockers — acceptable with pregnancy potential", ""]
      ]) + HY("Any woman who could become pregnant: no ACEI, no ARB.")),
      S("ckd-esrd", "Advanced CKD and ESRD", "<p>Frequently used because they are safe in ESRD: <strong>CCBs, beta-blockers, direct arterial vasodilators (hydralazine, minoxidil), and central α2-agonists (clonidine)</strong>. Clonidine is fairly strong and used for severe HTN in ESRD; hydralazine is safe in CKD/AKI; minoxidil is used for difficult HTN in renal failure. Loop diuretics need higher doses when GFR is low. Aldosterone antagonists and K-sparing diuretics carry hyperkalemia risk in CKD.</p>")
    ], [
      Q("black-patients", "Which antihypertensive classes work best as first-line therapy in Black patients without compelling indications?", ["CCBs and thiazide diuretics", "ACE inhibitors and ARBs", "Beta-blockers and alpha-blockers", "Clonidine and hydralazine"], 0, "CCBs and thiazides are more effective in Black patients; ACEIs/ARBs and beta-blockers are less effective."),
      Q("black-patients", "A 45-year-old White patient with uncomplicated stage 1 HTN needs one drug. Which is the first choice per the lecture?", ["ACE inhibitor or ARB", "Beta-blocker", "Alpha-1 blocker", "Loop diuretic"], 0, "White or non-Black patients under 60: ACEI or ARB first, followed by a CCB or thiazide."),
      Q("black-patients", "In which groups is ACE inhibitor angioedema more common?", ["Black and Asian patients", "White men", "Hispanic children", "Older White women"], 0, "Angioedema is more common in Black and Asian patients, and half of cases occur in the first week."),
      Q("older-adults", "In adults over 60, which BP component is the primary determinant of cardiovascular risk?", ["Systolic BP", "Diastolic BP", "Heart rate", "Mean arterial pressure only"], 0, "In younger patients diastolic BP tracks risk; after 60 isolated systolic HTN is common and systolic BP is the main determinant."),
      Q("older-adults", "An 82-year-old nursing-home resident with dementia and recurrent falls has BP 136/84 on repeated readings. What is reasonable?", ["Withhold antihypertensives and tolerate the higher BP", "Start two drugs now", "Start a thiazide and an alpha-blocker", "Admit for IV therapy"], 0, "Consider withholding drugs for stage 1 HTN in patients over 75 with falls, dementia, ECF residence, multiple comorbidities, orthostasis, or limited life expectancy."),
      Q("older-adults", "How should antihypertensive therapy be started in an older patient with isolated systolic hypertension?", ["Single agent at a low dose, titrated gradually", "Two drugs at full dose", "Three-drug combination", "IV therapy to reach goal quickly"], 0, "Older patients are more drug-sensitive: start low with one agent and titrate gradually; the target may be less aggressive."),
      Q("older-adults", "A 70-year-old woman with urinary incontinence, gout, and depression on sertraline needs a BP drug. Which class should be avoided?", ["Thiazide diuretic", "ACE inhibitor", "ARB", "DHP calcium channel blocker"], 0, "Avoid thiazides with gout, urinary incontinence, SSRI treatment, low sodium, or balance issues."),
      Q("pregnancy", "A 29-year-old woman planning pregnancy has stage 1 HTN. Which drug should be avoided?", ["Lisinopril", "Labetalol", "Nifedipine (extended release)", "Methyldopa"], 0, "With pregnancy potential, avoid ACEIs and ARBs (fetal renal agenesis). Labetalol, methyldopa, DHP-CCBs, thiazides, and beta-blockers are acceptable."),
      Q("pregnancy", "Which central alpha-2 agonist is one of the safest antihypertensives in pregnancy?", ["Methyldopa", "Clonidine", "Guanfacine", "Minoxidil"], 0, "Methyldopa is one of the safest drugs in pregnant hypertensives and is rarely used otherwise."),
      Q("pregnancy", "Which mixed alpha/beta-blocker is widely used in pregnancy and can be given IV?", ["Labetalol", "Carvedilol", "Propranolol", "Acebutolol"], 0, "Labetalol has a lot of experience in pregnancy, is safe, and is given orally or IV."),
      Q("ckd-esrd", "A patient on dialysis has severe hypertension. Which drug is described as safe and fairly strong in ESRD?", ["Clonidine", "Spironolactone", "Triamterene", "Lisinopril started by primary care"], 0, "Clonidine is safe in renal failure and fairly strong; CCBs, beta-blockers, and direct vasodilators are also frequently used in ESRD."),
      Q("ckd-esrd", "Which group of classes is frequently used in advanced CKD/ESRD because it is safe there?", ["CCBs, beta-blockers, direct vasodilators, and alpha-2 agonists", "ACEIs, ARBs, and aldosterone antagonists", "Thiazides and potassium-sparing diuretics", "Alpha-1 blockers and ENaC blockers"], 0, "CCBs, beta-blockers, direct arterial vasodilators, and alpha-2 agonists are safe in ESRD; RAAS blockers and K-sparing agents risk hyperkalemia.")
    ])
  ]);
}());
